INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(32, 'koKR', '', 'Proszę, oto twój raport. Usilnie radzę ci zanieść go komuś, kto ma praktyczną wiedzę w tych sprawach.$B$BZnam pewnego trolla uczonego, nazywa się Zilzibin Bębnoznawca. Spędził mnóstwo czasu na badaniu form życia, które występują wyłącznie w ekosystemie Azeroth, a do tego jest historykiem! Jeśli chcesz, żeby ktoś pomógł ustalić, czym dokładnie jest to zagrożenie i jak je powstrzymać, daj mu ten raport. Będziemy potrzebować wszelkiej możliwej pomocy.$B$BZil mieszka w domu na drugim poziomie Dziury w Orgrimmarze.', 'Zanieś raport Zilzibinowi Bębnoznawcy w Orgrimmarze.', '', '', '', '', '', '', 0),
(81, 'koKR', 'Dostawa sikacza', 'Pozwoliłem sobie zabezpieczyć w beczce nie tylko zapakowany sikacz Drana, lecz także dodatkowe butelki, które sobie przywłaszcza. Choć nie darzę Drana szczególnym szacunkiem, nie ma nic gorszego niż wstrząśnięty sikacz. Nie ma za co.$B$BA teraz dostarcz tę oto beczkę Dranowi Droffersowi do jego emporium złomu w Orgrimmarze. Bądź łaskaw przekazać Maltonowi moje najserdeczniejsze pozdrowienia; niech wie, że gdyby kiedykolwiek zapragnął przedniego trunku i jeszcze przedniejszego towarzystwa przy kielichu, jego wizyta będzie dla nas zaszczytem.', 'Dostarcz beczkę Dranowi Droffersowi w Orgrimmarze.', '', '', '', '', '', '', 0),
(235, 'koKR', 'Łowy w Jesionowej Kniei', 'Uwaga, młodzi śmiałkowie! Dzikie ostępy Jesionowej Kniei czekają na was!$B$BHorda mocno umocniła się na ziemiach na północ od Pustkowi. Nasze dwa posterunki – Posterunek Strzaskanego Drzewa i posterunek na Wybrzeżu Zoram – przysparzają Hordzie chwały! Kto chce się wykazać, niech tam szuka wskazówek. Zwłaszcza Senani Gromowe Serce w Posterunku Strzaskanego Drzewa, tuż na północ od Pustkowi, szuka śmiałków gotowych wziąć udział w wielkich łowach w Jesionowej Kniei!', 'Porozmawiaj z Senani Gromowe Serce w Posterunku Strzaskanego Drzewa w Jesionowej Kniei.', '', '', '', '', '', '', 0),
(649, 'koKR', 'Odzyskanie sikacza', 'Mam dla ciebie robotę przy odzysku, a jeśli jesteś $gtakim koneserem:taką koneserką; dobrego sikacza jak ja, to pokochasz to zadanie. Sikacz!$B$BTo napój, głąbie.$B$BW opuszczonym posterunku Hordy został zapas miodowego sikacza z Zaziemia z czasów, gdy posterunek jeszcze działał. Takiego sikacza już się nie dostanie! Jeden z tępych kumpli Maltona zna konkrety, więc ruszysz tam i przywieziesz mi skrzynkę zapakowanego sikacza, a do tego dwie butelki do mojej kolekcji! Pogadaj z Maltonem, on wprowadzi cię w szczegóły.', 'Porozmawiaj z Maltonem Droffersem w Orgrimmarze.', '', '', '', '', '', '', 0),
(650, 'koKR', 'Odzyskanie sikacza', 'Elf, z którym musisz pogadać, to Gilveradin Słońcogon. Samym węchem rozpozna każde wino, razem z rocznikiem! Zapakuje nam sikacz, więc musisz się z nim spotkać. Potrzebujemy sześciu butelek do zapakowania, dwóch dla taty i tylu, ile on sam zechce... a uwierz mi, zechce. Kiedy zapakujesz sikacz i zdobędziesz dwie butelki taty, wracaj tutaj!$B$BObóz Gilveradina jest niedaleko jakiejś stróżówki wysokich elfów w Zaziemiu, a tamte wysokie elfy nie są dobre. Uwierz mi.', 'Porozmawiaj z Gilveradinem Słońcogonem; jego obóz znajduje się w Zaziemiu.', '', '', '', '', '', '', 0),
(936, 'koKR', 'Pomoc dla arcydruida Runicznego Totemu', 'Wybacz, $N, ale jeśli to możliwe, chciałabym zająć ci chwilę.$B$BKrąg Cenariona w Gromowych Urwiskach bardzo chętnie przyjmie pomoc doświadczonych poszukiwaczy przygód takich jak ty przy niezwykle ważnym projekcie badawczym. Nie znam szczegółów, ale mogę ci powiedzieć, że badaniami kieruje nie kto inny jak Hamuul Runiczny Totem.$B$BJeśli cię to interesuje, porozmawiaj z nim osobiście na Wzniesieniu Starszych w samych Gromowych Urwiskach.', 'Porozmawiaj z arcydruidem Hamuulem Runicznym Totemem w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(1018, 'koKR', '', 'Uwaga, bohaterowie!$B$BKrąg Cenariona szuka sprawnych śmiałków, którzy pomogą mu badać rozległe, nowe rubieże Kalimdoru! Daleko na zachód od Tanaris i Gadżetonu leży zakazane pustkowie pełne niewyobrażalnych niebezpieczeństw, a Krąg potrzebuje chętnych i honorowych wysłanników, którzy będą działać w jego imieniu.$B$BWszyscy zainteresowani niech zgłoszą się do Kręgu Cenariona. Po więcej informacji udajcie się do arcydruida Hamuula Runicznego Totemu na Wzniesieniu Starszych w Gromowych Urwiskach!', 'Porozmawiaj z arcydruidem Hamuulem Runicznym Totemem na Wzniesieniu Starszych w Gromowych Urwiskach o wezwaniu Kręgu Cenariona do badania rubieży Kalimdoru.', '', '', '', '', '', '', 0),
(1061, 'koKR', 'Duchy Szponogłazów', 'Duchy Gór Szponogłazów są rozgniewane, bo gobliny i ich słudzy plądrują i palą tę ziemię. Ziemia zawołała więc, a ci, którzy nasłuchują takich wołań... usłyszeli.$B$BSeereth Łamikamień, obiecująca szamanka Hordy, została wysłana w Góry Szponogłazy. Donosi o masowym wyrębie lasów przez gobliny i prosi o pomoc.$B$BSpotkaj się z Seereth w Górach Szponogłazach. By do niej dotrzeć, idź drogą na zachód od Rozdroża na Pustkowiach. Rozbiła obóz w pobliżu Doliny Wielkiego Lasu.', 'Porozmawiaj z Seereth Łamikamień na granicy Gór Szponogłazów i Pustkowi.', '', '', '', '', '', '', 0),
(1145, 'koKR', 'Rój rośnie', 'Wielu podróżnych przechodzących przez Rozdroże pomogło mi zbierać jaja z Pola Olbrzymów i wielu z nich opowiada, jak śmiercionośne są te stwory. Nasłuchałem się dość, by uznać te owady za znacznie większe zagrożenie, niż moi zwierzchnicy początkowo sądzili.$B$BPotrzebuję gońca, który uda się do Orgrimmaru i spotka z Belgromem Skałomłotem. To nie jest błaha sprawa, więc powinien iść ktoś, kto potraktuje to zadanie poważnie.$B$BBelgroma zwykle można znaleźć przed siedzibą gildii wojowników.', 'Dostarcz zapieczętowany liścik Korrana Belgromowi Skałomłotowi w Orgrimmarze.', '', '', '', '', '', '', 0),
(1146, 'koKR', 'Rój rośnie', 'A więc Korran doszedł do podobnego wniosku co do tych owadów – wygląda na to, że stanowią większe zagrożenie, niż zakładaliśmy.$B$BKilka dni temu wrócił do mnie z Tysiąca Filarów ledwie żywy łowca. Należał do oddziału wysłanego, by przepędzić krasnoludzką ekipę wykopaliskową z Migoczących Równin. Podczas ataku z jaskini na wykopalisku wyroiło się więcej tych owadów i omal nie wybiło całego oddziału.$B$BDowodził nimi Moktar Krin, a teraz schronili się na skraju Migoczących Równin. Zanieś mu ten liścik.', 'Dostarcz zapieczętowany liścik Belgroma Moktarowi Krinowi w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1184, 'koKR', 'Części roju', 'Wracaj do Belgroma w Orgrimmarze i powiedz mu, że Moktar dobrze wykonuje jego rozkazy w Tysiącu Filarów. Powiedz mu też, że moje badania postępują i mam nadzieję wkrótce dowiedzieć się więcej. To go bardzo ucieszy.', 'Wróć do Belgroma Skałomłota w Orgrimmarze.', '', '', '', '', '', '', 0),
(1262, 'koKR', 'Raport dla Zora', 'Dziwne, że wisior, który ukradł Marg, był w rękach zwykłych żołnierzy. Może jego właściciel był przebrany, a może to sami żołnierze go ukradli!$B$BTak czy inaczej, to wisior szlachcica i musimy odkryć jego prawdziwego właściciela, jeśli mamy rozwikłać tę zagadkę.$B$BZanieś wisior Zorowi Samotnemu Drzewu w Orgrimmarze. Dobrze zna się na polityce Przymierza i będzie wiedział, czy ten wisior ma jakąś historię wśród szlachty Wichrogrodu.', 'Przynieś wysadzany klejnotami wisior Zorowi Samotnemu Drzewu w Orgrimmarze.', '', '', '', '', '', '', 0),
(1361, 'koKR', 'Regthar Brama Śmierci', 'Regthar Brama Śmierci, wojownik Hordy, werbuje śmiałków do misji na Mrocznym Pustkowiu. Jeśli chcesz się zgłosić, porozmawiaj z nim. Stacjonuje na Pustkowiach, w szeregu bunkrów na zachód od Rozdroża.$B$BI naostrz broń. Mroczne Pustkowie to kraina rozdarta wojną.', 'Porozmawiaj z Regtharem Bramą Śmierci na Pustkowiach.', '', '', '', '', '', '', 0),
(1431, 'koKR', 'Stosunki z Przymierzem', 'Spokojnie, $N. Pozwól, że podzielę się z tobą czymś ważnym dla naszego ludu, choć wcale nieoczywistym.$B$BJesteśmy dumną rasą, a wojna z ludźmi wystawiła na próbę nawet wielką cierpliwość Thralla. Widzisz, nasz wódz jest mądry i rozważny i niezmiennie stawia swój lud na pierwszym miejscu. Koniec końców jest dyplomatą, a w czasie spędzonym wśród ludzi wiele się nauczył o ich zwyczajach.$B$BJeśli ta opowieść cię zaciekawiła, odszukaj Keldrana przy zachodnim wyjściu z miasta. Tam stoi jego chata.', 'Porozmawiaj z Keldranem w Orgrimmarze.', '', '', '', '', '', '', 0),
(1432, 'koKR', 'Stosunki z Przymierzem', 'W miarę jak Przymierze zapuszcza się coraz głębiej w Kalimdor, może dojść do błędnego wniosku, że Horda zawiera pakty z Płonącym Legionem. Wódz nie może do tego dopuścić. Za jego błogosławieństwem biorę na siebie nadzór nad usunięciem tych demonów.$B$BMam agentów na Mrocznym Pustkowiu, w Posterunku Chodzącego z Duchami na północ od wielkiego Cmentarzyska Kodo. Ruszaj na południe od Zwęglonej Doliny w Górach Szponogłazach, a natkniesz się na niego. Gdy dotrzesz na miejsce, odszukaj Takatę Stalowe Ostrze.', 'Porozmawiaj z Takatą Stalowym Ostrzem na Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1433, 'koKR', 'Stosunki z Przymierzem', 'Płonące Ostrze ma wiele celów, ale wiedz, że jego członkowie są źli do szpiku kości, ich duchy są splugawione, a jedynym sposobem, by pokrzyżować ich plany, jest ich zniszczenie.$B$BKeldran wysłał ze mną Maurina, bo zna on Ostrze i jego czarnoksięskie sposoby.$B$BTo on kieruje naszymi planami przeciwko Ostrzu, a ja zajmuję się innymi demonicznymi zagrożeniami tu, na Mrocznym Pustkowiu.$B$BPorozmawiaj z nim, a wprowadzi cię w swoje zamysły.', 'Porozmawiaj z Maurinem Kościołupem na Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1434, 'koKR', 'Splugawieni przez satyrów', 'Plaga demonów nie pojawia się bez innych wpływów – coś innego pozwala złu zapuścić korzenie.$B$BMoże się zacząć od osłabionego ducha, od zbędnej żądzy władzy; może to pragnienie zemsty albo pokusa ostatecznej sprawiedliwości. Gdy dręczy nas ból, zło to wykorzystuje – zło takie jak satyry.$B$BZawiązały się więzi między nimi a Płonącym Ostrzem, a Thrall chce ich śmierci. Odszukaj je na północny wschód stąd i wróć do mnie, gdy je odeprzesz.', 'Zabij 7 łotrów Nienawistnej Furii, 7 zaprzysiężonych spaczeniu Nienawistnej Furii, 7 zdrajców Nienawistnej Furii i 7 przywoływaczy piekieł Nienawistnej Furii, a następnie wróć do Takaty Stalowego Ostrza na Mrocznym Pustkowiu.', '', 'Wróć do Takaty Stalowego Ostrza w Posterunku Chodzącego z Duchami na Mrocznym Pustkowiu.', '', '', '', '', 0),
(1435, 'koKR', 'Spalanie duchów', 'Śmierć to najlepszy los dla tych nikczemnych istot, które z tak samolubnych pobudek odwracają się od swego pana. Ale sama śmierć nie wystarczy, gdy ma się do czynienia z tymi, którzy oddali się ciemności.$B$BWeź ten klejnot. Gdy któryś z członków Płonącego Ostrza będzie bliski śmierci, uaktywnij jego magię. Zaklęcie wyrwie splugawionego ducha z ofiary, a na jego miejscu zostanie nasycony klejnot.$B$BPrzynieś mi te nasycone klejnoty, abym mógł się ich należycie pozbyć.$B$BA teraz idź i niech śmierć cię omija.', 'Zwróć płonący klejnot i 15 nasyconych płonących klejnotów Maurinowi Kościołupowi na Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(1436, 'koKR', 'Stosunki z Przymierzem', 'Walka idzie dobrze, $N. Jeśli nadal będziemy robić takie postępy w bitwie z demonami i ich sługusami, może wódz pozwoli nam wrócić do domów, zanim zmieni się pora roku.$B$BWróć do Keldrana i powiedz mu, czego dokonaliśmy. Jestem pewien, że wynagrodzi cię za twoje wysiłki. Jego sprawa jest dla niego ważna i będzie dumny, wiedząc, że wódz szanuje jego obawy.', 'Porozmawiaj z Keldranem w Orgrimmarze.', '', '', '', '', '', '', 0),
(1501, 'koKR', 'Stwór z Pustki', 'Zostało tak niewielu czarnoksiężników... Wiele ryzykujemy, ale to ryzyko jest uzasadnione. Musisz szybko dojrzeć w swoich umiejętnościach, jeśli masz być $gprzydatny:przydatna; dla Hordy i dla wodza.$b$bPora, byś $gnauczył:nauczyła; się nowego zaklęcia przyzywania.$b$bNajpierw musisz odzyskać tabliczkę Vergi, którą ukradli czarnoksiężnicy z Płonącego Ostrza. Przechowują ją teraz w swojej kryjówce przy Skale Czaszki na wschód od miasta. Gdy będę miał tabliczkę, pokażę ci runy potrzebne do przyzwania wędrowca Pustki.', 'Odzyskaj tabliczkę Vergi dla Gan\'rula Krwawego Oka w Orgrimmarze.', '', 'Wróć do Gan\'rula Krwawego Oka w Orgrimmarze.', '', '', '', '', 0),
(1504, 'koKR', '', 'Teraz przyjrzyj się tabliczce Vergi, bo zawiera glify, których będziesz potrzebować do przyzwania. Zanieś je do kręgu w namiocie Neeru Płomiennego Ostrza po drugiej stronie jaskini. Tam zdołasz wezwać wędrowca Pustki.$b$bMusisz go pokonać wszelkimi fizycznymi i magicznymi środkami, jakimi dysponujesz. Gdy to zrobisz, wróć do mnie z glifami przyzywania, a pokażę ci, jak podporządkować sobie tego stwora.', 'Za pomocą glifów przyzywania przyzwij i ujarzmij wędrowca Pustki, a następnie zwróć glify przyzywania Gan\'rulowi Krwawemu Oku w Orgrimmarze.', '', 'Wróć do Gan\'rula Krwawego Oka w Orgrimmarze.', '', '', '', '', 0),
(1507, 'koKR', '', 'Nadszedł czas, byś $gpoznał:poznała; więcej magii przyzywania. Nauczysz się przyzywać sukkuba, istotę o niezwykłych mocach umysłu. Potrafi omamić słabe umysły i uczynić je swoimi sługami – ale nie lękaj się! Jestem pewien, że sprostasz temu wyzwaniu.$b$bSukkuba można przyzwać tylko wtedy, gdy zwabi się go przedmiotem symbolizującym wielkie oddanie i miłość. Znalezienie takiego przedmiotu pozostawiam tobie.$b$bRada? Porozmawiaj z Cazulem... Niewiele jest rzeczy, których ten sędziwy czarnoksiężnik nie wie.', 'Porozmawiaj z Cazulem w Szczelinie Cienia.', '', '', '', '', '', '', 0),
(1508, 'koKR', 'Ślepy Cazul', 'Hmm... Ale rzecz jasna nie po to chcesz ze mną mówić.$b$bSkoro przysłał cię do mnie Gan\'rul, to zapewne masz przyzwać sukkuba i potrzebujesz przynęty.$b$bHmm... Jeśli ufasz, że ślepiec cię poprowadzi, $n, to słuchaj. Na urwiskach Orgrimmaru, na zachód od wieży wiwern, mieszka Zankaja. Czeka na powrót swojego towarzysza.$b$bIdź do niej.', 'Porozmawiaj z Zankają w Orgrimmarze.', '', '', '', '', '', '', 0),
(1509, 'koKR', 'Wieści o Dogranie', 'Mój towarzysz, Dogran, został niedawno wysłany na służbę na Rozdroże. To był awans i był z niego bardzo dumny.$b$bOczywiście było mi smutno, ale nie dałam mu tego po sobie poznać. I martwiłam się. Pustkowia są groźniejsze niż Orgrimmar i bałam się najgorszego.$b$bMinął już tydzień od dnia, w którym miał wrócić, a ja nie mam od niego żadnych wieści...$b$bMoże wybierzesz się na Rozdroże i sprawdzisz, czy mają tam jakieś wieści? Pracował z Gazrogiem, który powinien nadal tam stacjonować.', 'Porozmawiaj z Gazrogiem na Rozdrożu.', '', '', '', '', '', '', 0),
(1512, 'koKR', 'Dar miłości', 'Zankaja jest młoda i piękna. Być przykutą do kaleki... Nie pozwolę, by spotkała ją taka niesprawiedliwość.$b$bZostaw mnie, $n. I dziękuję. Mogę zakończyć życie w chwalebnej bitwie, zamiast wegetować jak pusta skorupa.$b$bI proszę, nie mów o tym mojej towarzyszce... Nie chcę, by dręczyło ją poczucie winy.', 'Przynieś oblepiony ziemią wisior Gan\'rulowi Krwawemu Oku w Orgrimmarze.', '', '', '', '', '', '', 0),
(1513, 'koKR', '', 'Zanieś to do kręgu przyzywania w namiocie Neeru, $n. Przyzwij plugawego sukkuba, a potem pokaż mu, kto tu jest panem. Wierzę w siłę twojej magii. Jak zawsze jednak bądź $gostrożny:ostrożna;, bo pycha i nadmierna pewność siebie zgubiły już niejednego obiecującego czarnoksiężnika.$b$bGdy go pokonasz, zwróć mi wisior, abym mógł przekazać wieści Zankai.', 'Za pomocą wisioru Dograna przyzwij i ujarzmij sukkuba, a następnie zwróć wisior Dograna Gan\'rulowi Krwawemu Oku w Orgrimmarze.', '', 'Wróć do Gan\'rula Krwawego Oka w Orgrimmarze.', '', '', '', '', 0),
(1522, 'koKR', '', 'Ogień jest z tobą. Widzę, że jesteś już $gsilny:silna; w drogach ziemi, i myślę, że jesteś $ggotów:gotowa; porozmawiać z Kranalem.$B$BKranal mieszka na północ od Rozdroża na Pustkowiach. Jest potężny w drogach żywiołów i może nauczyć cię dróg ognia... jeśli uważasz, że jesteś $ggotów:gotowa;.$B$BŁatwo go znaleźć, tylko nie zapuszczaj się za daleko – jak pójdziesz za daleko, trafisz na ziemie elfów.', '', '', '', '', '', '', '', 0),
(1528, 'koKR', '', 'W twojej przyszłości jest woda. Widzę, że jesteś już $gsilny:silna; w drogach ognia, i myślę, że jesteś $ggotów:gotowa; porozmawiać z Islen.$B$BIslen mieszka na wybrzeżu Pustkowi. Jak pójdziesz na południe wzdłuż Rzeki Południowej Furii, nie przegapisz jej – wypatruj wielkiego rekina! Jest potężna w drogach żywiołów i może nauczyć cię dróg wody... jeśli uważasz, że jesteś $ggotów:gotowa;.$B$BŁatwo ją znaleźć, tylko nie zapuszczaj się za daleko na południe – mieszka zaraz za Zapadką.', '', '', '', '', '', '', '', 0),
(1531, 'koKR', '', 'Robisz postępy. Jesteś $ggotów:gotowa; dowieść, że zasługujesz na totem powietrza, ale najpierw musisz odnaleźć Prate Chmurowieszczkę w Tysiącu Filarów. Powie ci, jak zdobyć totem powietrza, jeśli okażesz jej dość szacunku.$B$BIdź na południe przez Pustkowia, a gdy dotrzesz do Tysiąca Filarów, skręć na wschód. Znajdziesz ją w dziurze, gdzie siedzi ze swoim chłopakiem – ha ha, tylko nie mów jej, że się z niej nabijam, nie przyjęłaby tego zbyt dobrze.', 'Odnajdź Prate Chmurowieszczkę w Tysiącu Filarów.', '', '', '', '', '', '', 0),
(1823, 'koKR', 'Porozmawiaj z Rugą', 'Jesteś $gwojownikiem:wojowniczką; o dużych umiejętnościach i rosnącej sławie. Może jesteś $ggotów:gotowa; na próbę Rugi Gniewnego Totemu? Jeśli tak, odszukaj Rugę w Obozie Taurajo na Pustkowiach.$B$BCzeka na wojowników, którzy odpowiedzą na jego wezwanie.', 'Porozmawiaj z Rugą Gniewnym Totemem.', '', '', '', '', '', '', 0),
(1858, 'koKR', 'Strzaskana Dłoń', 'Otwarcie torby Tazana i dostarczenie mi jej zawartości zostawiam tobie. Mechanizm zamka jest skomplikowany, więc najprościej byłoby zdobyć klucz.$b$bSkoro nie $gznalazłeś:znalazłaś; go przy ciele Tazana, mogę tylko przypuszczać, że powierzył klucz komuś innemu... Ach tak, właśnie. Miał pomocnika imieniem Gamon. To pijak, najpewniej znajdziesz go w karczmie. Może zdołasz po cichu uwolnić go od tego klucza.', 'Ukradnij klucz Tazana, a potem otwórz nim jego torbę i dostarcz jej zawartość Therzokowi w Szczelinie Cienia w Orgrimmarze.', '', 'Wróć do Therzoka w Orgrimmarze.', '', '', '', '', 0),
(1943, 'koKR', 'Porozmawiaj z Deino', 'Trollowa magini Deino potrzebuje twojej pomocy, $N. Mieszka w Orgrimmarze, w Chacie Mrocznych Cierni.', 'Porozmawiaj z Deino.', '', '', '', '', '', '', 0),
(1944, 'koKR', 'Wody Xavian', 'Legendarne miasto Xavian leży ukryte głęboko we wschodniej części Jesionowej Kniei, a opowieści o jego pradawnej wiedzy są dobrze znane wśród uczonych. Mówi się, że wody Xavian mają ogromną moc magiczną.$B$BChciałabym dostać próbkę tych wód, wprost ze źródła.$B$BWeź tę flaszkę i udaj się do Xavian. Zaczerpnij wody u stóp najwyższego wodospadu i wróć do mnie. I uważaj, gdy będziesz przemierzać to pradawne miasto – ruiny należą teraz do satyrów, a one nie lubią, gdy magowie wtykają nos w ich sprawy.', 'Przynieś próbkę wody z Xavian magini Deino w Orgrimmarze.', '', 'Wróć do Deino w Orgrimmarze.', '', '', '', '', 0),
(1945, 'koKR', 'Roześmiane siostry', 'W zamian za twoje usługi zleciłam uszycie dla ciebie nowej szaty, o ile zdołasz zebrać potrzebne materiały...$B$BDo tej szaty musisz wrócić do Jesionowej Kniei po pukle włosów roześmianych sióstr – driad, które zbierają się w pobliżu Ustronia Raynewood.$B$BGdy zdobędziesz ich włosy, zanieś je Kil\'hali, trollowemu krawcowi na Rozdrożu na Pustkowiach. Będzie na ciebie czekał i uszyje twoją szatę.', 'Przynieś 12 włosów Roześmianej Siostry Kil\'hali na Rozdrożu.', '', 'Wróć do Kil\'hali na Rozdrożu na Pustkowiach.', '', '', '', '', 0),
(1963, 'koKR', 'Strzaskana Dłoń', 'Wódz jest zbyt subtelny w swoich metodach. Waha się, czy spuścić ze smyczy potęgę Hordy. Kiedyś byliśmy silniejsi, wszyscy byliśmy potężnymi zdobywcami. Tę dumę musimy odzyskać i Strzaskana Dłoń tego dokona.$b$bBudujemy siłę w cieniu i uderzamy tam, gdzie wróg się odsłoni, po kryjomu powalając naszych nieprzyjaciół. Musisz wykonać dla mnie zadanie, by dowieść swojej wartości.$b$bTroll Tazan handluje z piratami w pobliżu Zapadki. Ma informacje, których potrzebuję. Zabij go i przynieś mi jego torbę.', 'Zabij Tazana i przynieś jego torbę Therzokowi w Szczelinie Cienia w Orgrimmarze.', '', 'Wróć do Therzoka w Orgrimmarze.', '', '', '', '', 0),
(2019, 'koKR', 'Narzędzia fachu', 'Proszę, $n. Powinny ci dobrze posłużyć. Zrobiłem je własnoręcznie i przysięgam, że lepszych nie znajdziesz.$b$bNie trudź się jednak opowiadaniem mi o swoich sprawach. Nie interesują mnie intrygi Therzoka, chcę tylko w spokoju przeżyć swoją emeryturę.$b$bJeśli kiedyś będziesz potrzebować nowego kompletu narzędzi, wróć do mnie, a dam ci nowy. Ale obchodź się z nimi ostrożnie!', 'Wróć do Therzoka w Szczelinie Cienia w Orgrimmarze.', '', '', '', '', '', '', 0),
(2283, 'koKR', 'Odzyskanie naszyjnika', 'Mamy dla ciebie robotę, o ile starczy ci odwagi, żeby się jej podjąć!$B$BGłęboko na Bezludziu leżą wykopaliska Uldamanu. Słyszeliśmy o jakimś durnym paladynie, który niedawno tam zginął. A czemu nas to w ogóle obchodzi? Bo miał przy sobie bardzo cenny naszyjnik. Podobno ma trzy duże klejnoty: rubin, szafir i topaz.$B$BKonkret: chcemy go i płacimy SREBREM Z GÓRNEJ PÓŁKI. Może być uszkodzony, ale to bez znaczenia; wszelkie rysy sami naprawimy.', 'Odszukaj cenny naszyjnik na wykopaliskach Uldamanu i przynieś go Dranowi Droffersowi w Orgrimmarze. Naszyjnik może być uszkodzony.', '', 'Wróć do Drana Droffersa w Orgrimmarze.', '', '', '', '', 0),
(2284, 'koKR', 'Odzyskanie naszyjnika, podejście drugie', 'Pewne jak to, że Malton to matoł – te klejnoty wciąż są gdzieś w Uldamanie. Musisz tam wrócić i ich poszukać.$B$BJak mówiłem, jeśli nasze informacje się zgadzają, do naszyjnika pasują rubin, szafir i topaz. Znajdź je i osadź w naszyjniku.$B$BGdzie są te klejnoty? A kto to wie? Może dopisze ci szczęście i znajdziesz zwłoki paladyna. Jeśli nikt go jeszcze nie ogołocił, to może wciąż ma je przy sobie.', 'Znajdź w głębinach Uldamanu wskazówkę, gdzie mogą być klejnoty.', '', '', '', '', '', '', 0),
(2340, 'koKR', 'Dostarcz klejnoty', 'Każda oprawa naszyjnika i każdy klejnot się nadadzą, byle były z tego samego materiału. Ale to właśnie to źródło mocy przywróci naszyjnikowi magię... mam nadzieję.$B$BChętnie dostarczę klejnoty potrzebne do twojej wersji naszyjnika, o ile źródło mocy naprawdę zadziała.$B$BRuszaj do Orgrimmaru i dotrzymaj swojej części umowy ze Złomowiskiem Droffers i Syn. Tylko trzymaj język za zębami w sprawie naszej umowy, a kiedy wrócisz, może będę miał dla ciebie wspaniałą niespodziankę.', 'Dostarcz odzyskane naszyjniki i klejnoty Dranowi Droffersowi w Orgrimmarze.', '', '', '', '', '', '', 0),
(2341, 'koKR', 'Odzyskanie naszyjnika, podejście 3', 'Dran i Malton Droffersowie zaczynają się kłócić o nowy łup, więc połowa umowy jest już wypełniona. Czas na wyprawę na Bezludzie, by doprowadzić sprawę do końca – Jarkal Mchosplot w Kargacie może mieć tam dla ciebie specjalną nagrodę.', 'Odwiedź Jarkala Mchosplota w Kargacie i sprawdź, czy mu się udało.', '', '', '', '', '', '', 0),
(2378, 'koKR', 'Odnajdź Strzaskaną Dłoń', 'Dobrze $gsłużyłeś:służyłaś; tropicielom śmierci, $N, ale może pora, byś $gruszył:ruszyła; w szerszy świat. Choć $gwykazałeś:wykazałaś; talent do skradania się i podstępu, wciąż wiele musisz się nauczyć.$B$BTropiciele śmierci mają sojuszników w Strzaskanej Dłoni. Odszukaj tych, którzy zechcą nam pomóc – znajdź Shenthula w Orgrimmarze.$B', 'Udaj się do Orgrimmaru i porozmawiaj z Shenthulem w Szczelinie Cienia.$B', '', '', '', '', '', '', 0),
(2379, 'koKR', 'Zando\'zan', 'Sama determinacja nie wystarczy, by pokonać przeszkody, które nas czekają.$B$BPorozmawiaj z Zando\'zanem, by rozpocząć szkolenie na $gagenta:agentkę; Strzaskanej Dłoni.$B$BDopiero gdy opanujesz sztukę skradania się i złodziejstwa, będziesz $gmógł:mogła; zrobić kolejny krok ku swemu przeznaczeniu.$B', 'Porozmawiaj z Zando\'zanem w Szczelinie Cienia.', '', '', '', '', '', '', 0),
(2382, 'koKR', 'Wrenix z Zapadki', 'Zando\'zan to widział! Tak, ten dzień nadchodzi! Śmierć Thralla... sztylet w plecach, trucizna sącząca się do każdej żyły... Zando\'zan powiedział za dużo.$B$B$N! Zando\'zan ma zadanie, $N! $N musi udać się do Zapadki, na wschód od Rozdroża, i porozmawiać z Wrenixem Nędznym. Idź!$B', 'Udaj się do Zapadki na Pustkowiach i porozmawiaj z Wrenixem Nędznym.', '', '', '', '', '', '', 0),
(2458, 'koKR', 'Głęboka przykrywka', 'Spółka Gitgeszeft... Może o nich $gsłyszałeś:słyszałaś;?$B$BPrzez rok pracowaliśmy nad tym, by umieścić agenta głęboko w ich szeregach. Dzięki ciężkiej pracy i starannemu planowaniu to się udało.$B$BNiedawno dostaliśmy wiadomość, że spółka Gitgeszeft planuje coś na wielką skalę. Udaj się na północ od Naftowego Mokradła, do wieży spółki Gitgeszeft, i skontaktuj się z naszym tajnym agentem, nadzorcą Fizzule\'em.$B$BGdy znajdziesz wieżę, użyj tej rakietnicy, potem podejdź do Fizzule\'a i pokaż mu salut Strzaskanej Dłoni.$B', 'Udaj się do wieży spółki Gitgeszeft na północ od Naftowego Mokradła i skontaktuj się z tajnym agentem Strzaskanej Dłoni, nadzorcą Fizzule\'em.$B$BGdy wieża będzie w zasięgu wzroku, użyj rakietnicy, by dać nadzorcy Fizzule\'owi znać o swoim przybyciu. Wystrzel DWIE flary, a potem podejdź do nadzorcy Fizzule\'a i wykonaj salut Strzaskanej Dłoni (/salute).$B$BCzynności trzeba wykonać we właściwej kolejności, bo Fizzule zaatakuje i zlikwiduje każdego, kogo nie rozpozna.', '', '', '', '', '', '', 0),
(2460, 'koKR', 'Salut Strzaskanej Dłoni', 'Jako $głotr:łotrzyca; Strzaskanej Dłoni koniecznie musisz poznać salut Strzaskanej Dłoni. Tylko po nim da się naprawdę rozpoznać innego członka Dłoni.$B$BPatrz, ucz się, powtarzaj.', 'Wykonaj salut Strzaskanej Dłoni przed Shenthulem.', 'Salut Strzaskanej Dłoni wykonany', 'Wróć do Shenthula w Orgrimmarze.', '', '', '', '', 0),
(2478, 'koKR', 'Misja: możliwa, choć mało prawdopodobna', 'Musisz ukraść klucz do wieży brygadziście Silixizowi, $N. Kiedy już będziesz go mieć, zatrzymaj go – może mi się później przydać.$B$BPamiętaj, trucizna osłabiła wszystkich w tej wieży. Wykorzystaj swoje umiejętności, by siać chaos i zniszczenie wśród jej mieszkańców. Wybij ich wszystkich – bez litości!$B$BGdy wszystko w środku będzie leżeć w zakrwawionej stercie, otwórz wytrychem kasetkę Galiwiasza i wykradnij z niej zapas mikstury Zanzila. Zanieś głowę Galiwiasza i miksturę Shenthulowi w Orgrimmarze.', 'Ukradnij brygadziście Silixizowi klucz do wieży Silixiza, a następnie zabij dwóch zmutowanych robotników spółki Gitgeszeft, dwóch patrolowych spółki Gitgeszeft i dwie czujki spółki Gitgeszeft.$B$BZgładź wielkiego brygadzistę Galiwiasza i zabierz jego głowę, a potem otwórz wytrychem kasetkę Galiwiasza i wykradnij zapas zmienionej mikstury Zanzila. Zanieś zapas i głowę Galiwiasza Shenthulowi w Orgrimmarze po dalsze instrukcje.$B', '', 'Wróć do Shenthula w Orgrimmarze.', '', '', '', '', 0),
(2479, 'koKR', 'Pomoc Hinotta', 'Zanieś próbkę mikstury Serge\'owi Hinottowi do Smolnego Młyna.$B$BJeśli ktokolwiek może cię wyleczyć, to właśnie Serge. Jeśli pożyjesz wystarczająco długo, Serge nauczy cię sporządzać trucizny i ich używać.', 'Udaj się do Smolnego Młyna w Międzygórzu i dostarcz próbkę mikstury Zanzila Serge\'owi Hinottowi.$B$BAby dotrzeć do Smolnego Młyna, leć sterowcem do Podmiasta i idź drogą na południe przez Srebrzysty Bór w stronę Międzygórza. Kieruj się drogowskazami!$B$B', '', '', '', '', '', '', 0),
(2751, 'koKR', 'Barbarzyńskie blanki', 'Dwadzieścia pokoleń Omoshów dzierżyło ten młot, $N. Sto tysięcy ton metalu ukształtowaliśmy. Niestety, wszystko kończy się na Orokku, hańbie Omoshów: bez krewnych i niezdolnym do spłodzenia potomstwa.$B$BNie mogę pozwolić, by tajne receptury Omoshów umarły razem ze mną! Ktoś musi przejąć dziedzictwo, Omosh czy nie!$B$BUdowodnij Orokkowi, że się nadajesz, $N. Przynieś Orokkowi: dwie pary wzorzystych brązowych karwaszy, dwa brązowe wielkie miecze i dwa ostre pazury. Przynieś je Orokkowi, a pójdziemy dalej.', 'Przynieś dwie pary wzorzystych brązowych karwaszy, dwa brązowe wielkie miecze i dwa ostre pazury Orokkowi Omoshowi w Orgrimmarze.$B', '', 'Wróć do Orokka Omosha w Orgrimmarze.', '', '', '', '', 0),
(2752, 'koKR', 'O żelaznych naramiennikach', 'Orokk widzi zapał w twoich oczach, $N. Chłoniesz mądrość Omoshów jak gąbka.$B$BTrzech lekcji udzielę!$B$BWracaj do kowadła, nasiąknij żarem kuźni, zrób dla Orokka cztery brązowe topory bojowe i cztery brązowe młoty bojowe. Dopiero wtedy poznasz żelazny naramiennik.', 'Przynieś cztery brązowe topory bojowe i cztery brązowe młoty bojowe Orokkowi Omoshowi w Orgrimmarze.', '', 'Wróć do Orokka Omosha w Orgrimmarze.', '', '', '', '', 0),
(2753, 'koKR', 'Pod butem', 'Jeszcze tylko dwóch lekcji udzieli ci Orokk, $N. Wiem, że bolą cię mięśnie, ale nie ustawaj – dla Omoshów!$B$BPrzynieś Orokkowi cztery hełmy z zielonego żelaza, cztery pary karwaszy z zielonego żelaza i dwie pary nogawic z zielonego żelaza – ty się nauczysz, a twoi wrogowie ucierpią!', 'Przynieś cztery hełmy z zielonego żelaza, cztery pary karwaszy z zielonego żelaza i dwie pary nogawic z zielonego żelaza Orokkowi Omoshowi w Orgrimmarze.', '', 'Wróć do Orokka Omosha w Orgrimmarze.', '', '', '', '', 0),
(2754, 'koKR', 'Rogi szaleństwa', 'Ostatnia lekcja, której Orokk ci udzieli, $N. Wracaj do świętego kowadła i kuźni! Przynieś Orokkowi dwa solidne żelazne młoty, dwie pary butów z posrebrzanego brązu i dwie pary rękawic pancernych z posrebrzanego brązu.$B$BZobacz strach w ich oczach, gdy nadchodzisz!$B', 'Przynieś dwa solidne żelazne młoty, dwie pary butów z posrebrzanego brązu i dwie pary rękawic pancernych z posrebrzanego brązu Orokkowi Omoshowi w Orgrimmarze.', '', 'Wróć do Orokka Omosha w Orgrimmarze.', '', '', '', '', 0),
(2755, 'koKR', 'Radości Omoshów', 'Orokk nie płacze, $N. Sadza w oku.$B$B<Orokk ociera łzę.>$B$BZostał jeszcze jeden, ostatni sekret rodu Omoshów, którego Orokk cię nauczy. Orokk umrze szczęśliwy dzięki tobie, $N.$B$BNaucz się tańca radości Omoshów, a potem poznasz żelazną pięść!$B', 'Patrz i naucz się tańca radości Omoshów.', 'Taniec radości Omoshów opanowany', 'Wróć do Orokka Omosha w Orgrimmarze.', '', '', '', '', 0),
(2756, 'koKR', 'Dawne obyczaje', 'W czasach legend Aturk miażdżył czaszki wrogów i mielił kości na drobny proszek do wyrobu drutu. Te dni dawno minęły. Wódz wzywa do pokoju między klanami. Na dawnych wrogów patrzy się teraz tylko nieufnym okiem!$B$BNie do wiary, wiem, ale taka jest wola Thralla.$B$BDość narzekania! $GPrzyszedłeś:Przyszłaś; tu się uczyć, więc się nauczysz! Przynieś mi cztery stalowe napierśniki i cztery stalowe hełmy, a zasmakujesz wojny!', 'Przynieś cztery stalowe napierśniki i cztery stalowe hełmy płytowe Aturkowi Kowadłu w Orgrimmarze.$B', '', 'Wróć do Aturka Kowadła w Dolinie Honoru w Orgrimmarze.', '', '', '', '', 0),
(2757, 'koKR', 'Łupieżcza Zatoka albo nic!', 'Słuchaj, $gmłody:młoda;, niczego się nie nauczysz, kręcąc się tutaj.$B$BZnam gościa, który zna gościa. Kręci się przy kuźni w Łupieżczej Zatoce. Jak pokażesz mu tę odznakę, opowie ci wszystko o mithrilu.$B$BTo jak będzie? Zostaw te dziecinady bobasom w pieluchach, $N – czas iść dalej.$B$BJeśli cię to interesuje, nazywa się McGavan. Pokaż mu ten znaczek, a pozna, że traktujesz sprawę poważnie.', '', '', '', '', '', '', '', 0),
(2950, 'koKR', 'Nogg poprawia pierścień', 'Nie, nie, nie – wcale nie twierdzę nagle, że pierścień jest mój. Zwykle tego nie robię, ale twoje informacje o Czarnorytych bardzo się przydały. Ulepszę ci ten pierścień lepiej, niż potrafiłby ktokolwiek, kto zrobił to proste cacko. Pewnie jakiś gnom...$B$BJeśli przyniesiesz mi sztabkę srebra, agat mszysty i trzydzieści srebrnych monet za fatygę, dodam do pierścienia ażurową oprawę ze srebra i agatu, która wzmocni zaklętą w nim magię. Wchodzisz w to?', 'Przynieś błyszczący złoty pierścień, sztabkę srebra, agat mszysty i 30 srebrnych monet Noggowi w Orgrimmarze.', '', '', '', '', '', '', 0),
(2976, 'koKR', 'Ponure odkrycie', 'Co?!$B$BAch, czyli wspomniałem o nagrodzie, tak? No, to mnie nauczy trzymać język za zębami.$B$BTo ty $gwykonałeś:wykonałaś; robotę, więc chyba słusznie, żeby największa nagroda przypadła tobie. Weź rogi, każę je dla ciebie zapakować do skrzyni. Znajdź Belgroma Skałomłota w Dolinie Honoru – będzie chciał wiedzieć, co $gwidziałeś:widziałaś;, i wynagrodzi cię za ciężką pracę.$B$BTrzymaj się, $N, i jeszcze raz dzięki za wszystko, co $gzrobiłeś:zrobiłaś;.', 'Zanieś skrzynię rogów Ponurych Totemów Belgromowi Skałomłotowi w Orgrimmarze.', '', '', '', '', '', '', 0),
(2981, 'koKR', 'Zagrożenie w Feralas', 'Feralas to idealne miejsce, by ktoś o twoich umiejętnościach mógł się wykazać. Dominującą siłą zbrojną jest tam plemię ogrów zwane Gordunni, a ich liczba rośnie. Trzeba ich powstrzymać, zanim zagrożą naszej obecności w Feralas.$B$BZnam wojowniczkę imieniem Rok Orhan, która przebywa w Obozie Mojache w Feralas – idź do niej. Gdy przybędziesz, opowie ci więcej o sytuacji.', 'Belgrom Skałomłot chce, żebyś $gporozmawiał:porozmawiała; z Rok Orhan w Obozie Mojache.', '', '', '', '', '', '', 0),
(2996, 'koKR', '', 'Uczyłem cię już wcześniej, ale nadszedł czas, by uczył cię ktoś inny. Jest w Zapadce i nazywa się Strahad. To człowiek, ale niech cię to nie zwiedzie – nie myśl, że jest słaby. Choć może i niewielki, ma wielką moc. Nauczy cię potężniejszych przywołań – czuję, że jesteś $ggotów:gotowa;. Idź do niego teraz. Jest w Zapadce... ponad portowym miasteczkiem, przy swojej wieży.', 'Porozmawiaj ze Strahadem Farsanem w Zapadce.', '', '', '', '', '', '', 0),
(3002, 'koKR', 'Kula Gordunni', 'Choć dobrze znam swojego wroga, jestem wojowniczką, $N. Nie mam pojęcia, do czego zdolna jest ta kula.$B$BZnam w Orgrimmarze maga, który powie nam o niej więcej. Zanieś mu ją.', 'Zanieś kulę Gordunni Uthel\'nayowi w Chacie Mrocznych Cierni w Orgrimmarze.', '', '', '', '', '', '', 0),
(3504, 'koKR', 'Zdrada', 'Zdradziecka złodziejka! Tak ją nazywam – i nikim innym nigdy nie będzie!$B$BChyba popełniłem poważny błąd, $N. Zaufałem krwawej elfce. Co gorsza, zaufałem kobiecie!$B$BTwierdziła, że w Aszarze czekają wielkie bogactwa... potężne przedmioty. Miałem tylko wysłać z nią kilku wojowników do ochrony, a potem dostać nagrodę. No i proszę, kto wyszedł na głupca – wybiła ich wszystkich.$B$BPragnę zemsty, $N, ale nie stać mnie na wysłanie nikogo więcej. Znajdź Ag\'tora w Valormok, na północ od Obozowiska Haldarr. On powie ci więcej.', 'Dostarcz zapieczętowany list do Ag\'tora Ag\'torowi Krwawej Pięści w Aszarze.', '', '', '', '', '', '', 0),
(3505, 'koKR', 'Zdrada', 'Tak myślałem.$B$BZaczniemy krucjatę od jej robotników na południowych urwiskach północnego półwyspu Aszary. Zabijaj ich w krwawym szale – niech wiedzą, że zdradzili niewłaściwych sojuszników.$B$BNią samą na razie się nie przejmuj – większość czasu spędza z ochroniarzami, przeszukując Aszarę. Kiedy już wybijesz jej robotników, dobrze byłoby znaleźć jej prywatny obóz. Warto wypatrzyć, gdzie możemy ją zaatakować. Może znajdziesz tam coś, czym da się ją sprowokować.', 'Zabij 10 odzyskiwaczy krwawych elfów i 10 mierniczych krwawych elfów, a następnie odszukaj obóz magini Rimtori. Gdy go znajdziesz, poszukaj czegoś, co może być dla niej ważne i czym da się ją wywabić do walki.', 'Znajdź obóz magini Rimtori', 'Wróć do Księgi przywołań kaldorei w Obozowisku Legash w Aszarze.', '', '', '', '', 0),
(3506, 'koKR', 'Zdrada', 'Po chwili namysłu do głowy przychodzi ci kilka pomysłów, a jeden z nich wywołuje uśmiech na twojej twarzy: może zniszczenie kryształów rozzłości krwawą elfkę winną rzezi tylu orków i zdrady Belgroma?$B$BOdcyfrowujesz dalej pismo i rysunki i uświadamiasz sobie, że jeden z kryształów jest związany z twórcą kręgu – pozostałe wiążą się z czymś znacznie bardziej złowrogim.$B$BZamykasz księgę i zastanawiasz się, który kryształ zniszczyć.', 'Zniszcz tajemny kryształ skupiający związany z maginią Rimtori, a potem ją zabij. Następnie zanieś głowę magini Rimtori Ag\'torowi Krwawej Pięści w Aszarze.', '', 'Wróć do Ag\'tora Krwawej Pięści w Aszarze.', '', '', '', '', 0),
(3507, 'koKR', 'Zdrada', 'Wróć do Belgroma w Orgrimmarze. Sam będzie chciał zobaczyć jej głowę! My też niedługo tam wrócimy.$B$BAch, to naprawdę dobry dzień. Dziękuję za pomoc, $N.', 'Porozmawiaj z Belgromem Skałomłotem w Orgrimmarze.', '', '', '', '', '', '', 0),
(3541, 'koKR', 'Dostawa dla Jes\'rimona', 'Mam w Orgrimmarze pasera. Siedzi w Dziurze. Trudno go namierzyć, jeśli nie wiesz, gdzie szukać, ale jeśli rozejrzysz się w jednym z najwyższych budynków, nie powinno być problemu.$B$BWyświadcz mi jednak przysługę i nie rozgłaszaj po całym Kalimdorze, że on tam jest i czym się zajmuje – źle by się to skończyło dla nas obojga.$B$BZapłaci nam więcej niż uczciwą cenę za tabliczkę Jin\'yael. Nie wiem czemu, ale szkoda, że nie $gwidziałeś:widziałaś;, jak się podekscytował, gdy usłyszał, gdzie ona jest.', 'Zanieś tabliczkę Jin\'yael Jes\'rimonowi w Orgrimmarze.', '', '', '', '', '', '', 0),
(3563, 'koKR', 'Zapłata Jes\'rimona dla Jedigi', 'Zanieś ten list Jedidze. Powiedz jej, że nasz układ się opłacił i że jestem zadowolony z jej roboty.$B$BPowiedz jej, żeby szybko wracała do Orgrimmaru, a Jes\'rimon już się nią dobrze zaopiekuje.$B$BPowiedz jej to, a może w przyszłości znów będę potrzebował twoich usług, $N.', 'Dostarcz liścik Jes\'rimona Jedidze w Aszarze.', '', '', '', '', '', '', 0),
(3923, 'koKR', 'Rilli Tłustogęby', 'No, to nie zadziałało. Założyłam na samoflanż dodatkowe wskaźniki do pomiaru wytrzymałości konstrukcji, a pokazały ją na najniższym poziomie w historii. Mogłabym dołożyć jeszcze kilka tarcz i może dźwignię czy dwie, żeby spróbować go naprawić, ale... chyba tylko bym pogorszyła sprawę.$B$BZanieś samoflanż Rilliemu Tłustogębemu. Kiedyś pracował dla spółki Gitgeszeft – jeśli ktoś wie, jak to naprawić, to właśnie Rilli.$B$BZnajdziesz go w Warsztacie mechanicznym Nogga w Dolinie Honoru w Orgrimmarze.', 'Zanieś zepsuty i poobijany samoflanż Rilliemu Tłustogębemu w Orgrimmarze.', '', '', '', '', '', '', 0),
(3924, 'koKR', 'Instrukcja samoflanża', 'Chyba dam radę naprawić samoflanż, ale najpierw potrzebuję instrukcji obsługi. Kiedy byłem w spółce Gitgeszeft, miałem rywala, szefa Miedziowtyka, który strzegł tajemnic samoflanża i dzielił się okruchami wiedzy o tym urządzeniu tylko z zaufanymi. Ja do tych nielicznych zaufanych nie należałem...$B$BSzef Miedziowtyk przesiadywał w Kopalni Głazowej Żyły w północno-wschodniej części Pustkowi. Zdobądź od niego instrukcję, a jeśli rozdał komuś jej strony, będziesz $gmusiał:musiała; zebrać i je.', 'Przynieś instrukcję samoflanża Rilliemu Tłustogębemu w Orgrimmarze.', '', 'Wróć do Rilliego Tłustogębego w Orgrimmarze.', '', '', '', '', 0),
(4001, 'koKR', 'Co się dzieje?', 'Jak dotąd moje porozumienie z krasnoludem Kharanem, z celi po drugiej stronie korytarza, było ograniczone. Zdołałem go jednak przekonać, że ja, a raczej -my- nie chcemy go skrzywdzić.$B$BIdź z nim porozmawiać i zbierz jak najwięcej informacji o księżniczce i jej porywaczach. Zanieś te informacje wodzowi.$B$BThrall nie chce, by księżniczce stała się krzywda – ma za to wielki plan, który zakłada jej bezpieczny powrót do Żelaznej Kuźni. Kharan już to wszystko wie... Idź!$B', 'Porozmawiaj z Kharanem Potężnym Młotem i zbierz informacje o porwaniu księżniczki Moiry Miedziobrodej. Zanieś te informacje Thrallowi w Orgrimmarze.$B$BPamiętasz, jak Gor\'shak wspominał, że Kharana trzymają w pobliskiej celi.$B', 'Informacje od Kharana zebrane', 'Wróć do Thralla w Fortecy Grommasza w Orgrimmarze.', '', '', '', '', 0),
(4002, 'koKR', 'Wschodnie Królestwa', 'Przynosisz doskonałe informacje, $N.$B$BJako wódz mam obowiązek czynić to, co najlepsze dla Hordy. Dopilnować, by pokolenia, które przyjdą po nas, nie były skazane na beznadziejny byt.$B$BOkazja, by ukształtować nasze przyszłe sojusze, sama wpadła nam w ręce. Pomoc krasnoludom mogłaby znacznie wzmocnić nasze stosunki we Wschodnich Królestwach. Dlatego właśnie nie możesz zawieść!$B$BJesteś $ggotów:gotowa;?', 'Porozmawiaj z Thrallem, jeśli jesteś $ggotów:gotowa; podjąć się zaplanowanej przez niego misji.', '', '', '', '', '', '', 0),
(4003, 'koKR', 'Królewski ratunek', 'Ten cios w krasnoludy z klanu Czarnorytych, jeśli się powiedzie, wstrząśnie całym ich królestwem.$B$BKsiężniczka Miedziobroda jest pod władzą imperatora Thaurissana. Aby ją uwolnić, musisz zabić imperatora. Uważaj, twoje zadanie jest podwójnie niebezpieczne, bo dopóki imperator nad nią panuje, Miedziobroda bez wahania cię zaatakuje.$B$BNIE WOLNO CI JEJ SKRZYWDZIĆ!', 'Zabij imperatora Dagrana Thaurissana i uwolnij księżniczkę Moirę Miedziobrodą spod jego złego czaru.$B', '', '', '', '', '', '', 0),
(4004, 'koKR', 'Księżniczka uratowana?', '$GZabiłeś:Zabiłaś; mojego męża! Moje dziecko przyjdzie na świat bez ojca.$B$B<Księżniczka Moira wskazuje prosto na ciebie.>$B$BZapewniam cię, że to dziecko zostanie następnym władcą królestwa Żelaznej Kuźni. Ty i tobie podobni będziecie ścigani aż po kres dni za ten niegodziwy czyn.$B$B<Przychodzi ci do głowy, że księżniczka Moira może wciąż cierpieć od resztek czaru Thaurissana.>$B$BZostaw mnie w spokoju. Jestem pewna, że twój wódz z niecierpliwością wysłucha, czym skończyło się jego wtrącanie.$B', 'Wróć do Thralla w Fortecy Grommasza w Orgrimmarze.$B', '', '', '', '', '', '', 0),
(4300, 'koKR', 'Broń z kościanymi ostrzami', 'Hmm, jak tak myślę, to może jest coś, co możesz teraz zrobić dla Dłoni. Tak, Jes\'rimonowi na pewno przyda się twoja pomoc.$B$BW Kraterze Un\'Goro żyją raptory o śmiercionośnych pazurach. Niektóre z nich mają czasem białe pazury zamiast czarnych jak śmierć. Dłoń ma... klientów... którzy lubią broń zrobioną z tych pazurów. Przynieś mi dużo tych białych pazurów, a dobrze ci zapłacę. Uwiń się szybko, a może pomogę ci też na inne sposoby.', 'Przynieś 8 pazurów białego plądrozaura Jes\'rimonowi w Orgrimmarze.', '', 'Wróć do Jes\'rimona w Orgrimmarze.', '', '', '', '', 0),
(4509, 'koKR', '', 'Moje najnowsze odkrycia i wiedza, którą dziś tu zdobyliśmy, muszą trafić w ręce, które mogą coś z nimi zrobić. Choć tu, w Gadżetonie, jesteśmy bardzo zaradni, sami temu nie podołamy.$B$BZanieś mój najnowszy raport Zilzibinowi Bębnoznawcy do Orgrimmaru; wciąż siedzi u siebie w górnej części Dziury, prawda? Ma przyjaciół wysoko w Hordzie; jeśli uda nam się ich w to wciągnąć, $N, może wyjdziemy z tego cało.', 'Zanieś raport Pestlezugga z Un\'Goro Zilzibinowi Bębnoznawcy w Orgrimmarze.', '', '', '', '', '', '', 0),
(4511, 'koKR', '', '$N, bez ciebie nie zaszlibyśmy tak daleko. Bez wątpienia wkrótce nadejdzie czas, gdy znów poproszę cię o pomoc w walce z silithidami. Musimy przetrawić to, czego dowiedzieliśmy się w Un\'Goro; obawiam się, że myliłem się, zakładając, że silithidy pochodzą z Un\'Goro... że gdzieś istnieje ich znacznie silniejsze skupisko.$B$BZanieś ten liścik Karusowi w banku. Da ci coś z mojego skarbca – potraktuj to jako wyraz mojej wdzięczności. Dziękuję za pomoc, $gpotężny:potężna; $N.', 'Zanieś bon bankowy Karusowi w banku Orgrimmaru.', '', '', '', '', '', '', 0),
(4737, 'koKR', '', 'Hmf, wciąż dążysz do większej mocy. Mówię ci, to tylko kwestia czasu, aż owładnie tobą zepsucie i nałóg, a staniesz się niewolnikiem tego, nad czym chcesz zapanować.$B$BPfff! Głupiec z ciebie! Czas przyzna mi rację – nic innego... tylko czas.$B$BAle wygląda na to, że nie wszyscy zgadzają się z Zevrostem. Menara najwyraźniej chce stworzyć dla ciebie narzędzia, dzięki którym zyskasz więcej mocy i zapanujesz nad swoją siłą. Jeśli cię to interesuje, udaj się do Zapadki na Pustkowiach. Jest tam i spogląda na miasteczko z góry.', '', '', '', '', '', '', '', 0),
(4941, 'koKR', 'Mądrość Eitrigga', 'Rwij żyje?$B$BNiemożliwe!$B$BSądzono, że Rwij zginął dziesiątki lat temu.$B$BZasięgnij rady mądrego Eitrigga, $N. Nikt nie zna poczynań klanu Czarnej Skały lepiej niż on, a jeśli to, co tu napisano, jest prawdą, Eitrigg powinien się o tym dowiedzieć. Nikomu nie wolno odmawiać prawa do zemsty.$B$BZnajdziesz go w Orgrimmarze.$B$BGdy już porozmawiasz z Eitriggiem, naradź się z wodzem i dowiedz się, co zamierza zrobić z tym problemem.', 'Porozmawiaj z Eitriggiem w Orgrimmarze. Gdy omówisz z nim sprawę, zasięgnij rady Thralla.$B$BPrzypominasz sobie, że $gwidziałeś:widziałaś; Eitrigga w komnacie Thralla.', 'Narada z Eitriggiem.', 'Wróć do Thralla w Orgrimmarze.', '', '', '', '', 0),
(4967, 'koKR', '', 'Wciąż ten sam głupiec, wciąż uganiasz się za świecidełkami śmiertelników. Tak, mówię do ciebie z arogancją. Patrzę na ciebie i się śmieję. Jesteś $gżałosny:żałosna;!$B$BAle nieważne, co ja myślę. Liczy się tylko to, co myślą ci, którzy zechcą mieć z tobą do czynienia! A w tym przypadku, wbrew mojemu zdrowemu rozsądkowi, ci, którzy mają choć odrobinę władzy, uważają, że zasługujesz na więcej.$B$BJeśli do tego dążysz, porozmawiaj z Menarą Rozdzieraczką Pustki w wieży nad Zapadką. Zdaje się, że już ją kiedyś $gspotkałeś:spotkałaś;.', '', '', '', '', '', '', '', 0),
(4974, 'koKR', 'Za Hordę!', 'Rwij pozwala sobie na tak wielkie roszczenia, bo chroni go Czarne Stado.$B$BTy, $N, znajdziesz sposób, by przejść przez Sale Wniebowstąpienia. Potem odnajdziesz „Wodza Wojennego” Rwija Czarnorękiego i zniszczysz go – ZA HORDĘ!$B$B<Thrall uderza pięścią w tron.>$B$BGdy następnym razem wrócisz do mojej komnaty, uniesiesz triumfalnie jego głowę, a potem złożysz ją przed swoim wodzem. Zrób to, a zostaniesz $guhonorowany:uhonorowana; jako $gbohater:bohaterka; Hordy.', 'Udaj się do Iglicy Czarnej Góry i zabij Wodza Wojennego Rwija Czarnorękiego. Zabierz jego głowę i wróć do Orgrimmaru.', '', 'Wróć do Thralla w Orgrimmarze.', '', '', '', '', 0),
(5093, 'koKR', '', 'Bohaterowie królestwa, posłuchajcie mnie – Horda wzywa was do szybkiego działania!$B$BOgłoszono wezwanie do broni dla wszystkich zdolnych do walki, by chwycili za oręż przeciw Pladze! Krążą plotki o nowych zagrożeniach, które powstają z ruin Wschodnich Królestw. Czają się na wschód od Podmiasta, w północnych rubieżach krain znanych dziś jako Plagowiska!$B$BBohaterowie królestwa – odszukajcie najwyższego egzekutora Derringtona, który rozbił obóz na Barykadzie, na wschód od Polan Tirisfal!', 'Odszukaj najwyższego egzekutora Derringtona. Jego obóz znajduje się na Barykadzie, na wschód od Polan Tirisfal i Podmiasta.', '', '', '', '', '', '', 0),
(5301, 'koKR', '', 'Satysfakcja. To ją czerpię z młota i kowadła. Widok dumnego wojownika Hordy, którego chroni moja stal, przypomina mi, co znaczy żyć. To nałóg, którego nigdy nie odważę się rzucić, $N.$B$BNie mogę dać ci tej satysfakcji, mogę tylko wskazać ci ścieżkę. Jak każde życiowe przedsięwzięcie, ścieżka płatnerza jest podróżą.$B$BJeśli chcesz należeć do nielicznych wybranych, wystarczy poprosić, a cię wyszkolę – najpierw jednak musisz wykonać zadanie.', 'Aby zostać $gpłatnerzem:płatnerką;, musisz wykonać następujące przedmioty i przynieść je Okothosowi: 4 zdobione mithrilowe hełmy, 2 pary zdobionych mithrilowych butów, 1 zdobiony mithrilowy napierśnik.', '', 'Wróć do Okothosa Żelaznego Szału w Orgrimmarze.', '', '', '', '', 0),
(5302, 'koKR', '', 'Pewnego dnia stworzę legendarny młot. Młot godny wodza!$B$BTo dzieło mojego życia, $N. Moja pasja. Widzę, że masz w sobie potencjał, by być wśród nas, jednym z nas – $gkowalem:kowalką; broni. To ja mogę ci pomóc ten potencjał wykorzystać.$B$BMusisz tylko wykonać proste zadanie. Proste dla kogoś o tak wyjątkowych umiejętnościach.', 'Aby zostać $gkowalem:kowalką; broni, musisz wykonać następujące przedmioty i przynieść je Borgoshowi: 4 pałasze z księżycowej stali, 4 masywne żelazne topory, 2 ciężkie mithrilowe topory i 2 duże czarne buzdygany.$B', '', 'Wróć do Borgosha Gnącego Rdzeń w Orgrimmarze.', '', '', '', '', 0),
(5726, 'koKR', 'Ukryci wrogowie', 'Jednego nie będę tolerował: zdrajców w naszych szeregach, $N. Ale byłbym głupcem, gdybym tak wcześnie odkrył karty – nie wyciąłbym w ten sposób zepsucia z naszych ziem, a tylko pogorszyłbym zakażenie.$B$BAle ty, $gmłody poszukiwaczu:młoda poszukiwaczko; przygód, możesz dotrzeć tam, gdzie moi agenci nie mogą... możesz poznać prawdę... możesz znaleźć prawdziwą głowę bestii.$B$BJeśli starczy ci odwagi, wejdź do Skały Czaszki na wschód od Orgrimmaru, zdobądź odznakę porucznika od któregoś z członków Płonącego Ostrza i wróć do mnie.', 'Przynieś Insygnia porucznika Thrallowi w Orgrimmarze.', '', 'Wróć do Thralla w Orgrimmarze.', '', '', '', '', 0),
(5727, 'koKR', 'Ukryci wrogowie', 'Zobaczmy teraz, czy insygnia, które $gznalazłeś:znalazłaś;, są warte zachodu.$B$BW mieście jest czarnoksiężnik, który sądzi, że cieszy się moim zaufaniem. Nie wie, że zdaję sobie sprawę, komu naprawdę jest wierny. W rzeczywistości to przywódca Płonącego Ostrza. Ale nie rzucaj się na niego z bronią; ma on swoje zadanie, a my wykorzystamy go przeciwko naszym wrogom.$B$BZanieś mu te insygnia do Szczeliny Cienia tu, w Orgrimmarze, porozmawiaj z nim i sprawdź, czy uzna cię za $gjednego:jedną; ze swoich, a potem wróć do mnie.', 'Zanieś Insygnia porucznika Neeru Płomiennemu Ostrzu i porozmawiaj z nim. Oceń, czy uważa cię za członka Płonącego Ostrza, a potem wróć do Thralla w Orgrimmarze.', 'Sprawdź, jak Neeru Płomienne Ostrze reaguje na ciebie jako członka Płonącego Ostrza', 'Wróć do Thralla w Orgrimmarze.', '', '', '', '', 0),
(5728, 'koKR', 'Ukryci wrogowie', 'Hmm, przywódcy Palącego Ostrza... to niepokoi mnie najbardziej. Jeśli to oni są cenni dla Neeru, to na nich musimy uderzyć najpierw. Ten satyr... Bazzalan, i ten drugi, o którym wspominał Neeru – kim on był, czarnoksiężnikiem? – muszą zginąć.$B$BWróć do Szczeliny Cienia i wejdź do Rozpadliny Wściekłego Ognia, $N. Znajdź tych dwóch przywódców Palącego Ostrza i zabij ich. Ale uważaj, by Neeru nie dowiedział się, że to twoja sprawka. Musisz nadal uchodzić za $gjednego z jego braci:jedną z jego sióstr; broni.', 'Zabij Bazzalana i Jergosha Inwokatora, a potem wróć do Thralla w Orgrimmarze.', '', 'Wróć do Thralla w Orgrimmarze.', '', '', '', '', 0),
(5729, 'koKR', 'Ukryci wrogowie', 'Myślę, że następnym krokiem powinno być umieszczenie cię blisko Neeru. Jeśli jest tak wzburzony, jak donoszą, możemy upiec dwie pieczenie na jednym ogniu. Po pierwsze, możesz dowiedzieć się czegoś więcej o Radzie, a przynajmniej o Płonącym Ostrzu, a po drugie, może zacznie ci ufać na tyle, że poprosi cię o pomoc. Może nawet uznać, że zdołasz wypełnić lukę teraz, gdy część przywódców jest w rozsypce.$B$BWróć do Szczeliny i porozmawiaj z nim ponownie, ale nie bądź zbyt $gnachalny:nachalna;.', 'Porozmawiaj z Neeru Płomiennym Ostrzem w Orgrimmarze.', '', '', '', '', '', '', 0),
(5730, 'koKR', 'Ukryci wrogowie', 'Należysz do moich poruczników! Przygotuj się, $N. Wkrótce cię wezwę.$B$BCzas, który poświęciłem Palącemu Ostrzu, może teraz pójść niemal na marne, ale to nie znaczy, że plany Rady Cieni w innych miejscach mają na tym ucierpieć. Zrobię, co w mojej mocy, by ograniczyć straty tu, w Rozpadlinie Wściekłego Ognia. Tymczasem moi agenci na Pustkowiach i w Jesionowej Kniei zajmą się naszym najnowszym planem. Wróć do mnie niedługo.', 'Porozmawiaj z Thrallem w Orgrimmarze i powiedz mu, czego się $gdowiedziałeś:dowiedziałaś;.', '', '', '', '', '', '', 0),
(5761, 'koKR', 'Ubicie bestii', 'Najważniejsze zadanie, jakie powierzył mi nasz wielki wódz, to wytępić stwory odpowiedzialne za zatruwanie wielkiego miasta naszego pana demonicznymi wpływami. Płonące Ostrze to jedno zagrożenie, ale są i inne – na przykład Palące Ostrze, które zagnieździło się w Rozpadlinie Wściekłego Ognia i potajemnie próbuje zdeprawować niewinnych członków Hordy.$B$BJeśli mamy ich powstrzymać, musi zginąć ich przywódca – strażnik Spaczenia imieniem Taragaman Łaknący.$B$BZabij go, a jego serce zadowoli Thralla, tego jestem pewien.', 'Wejdź do Rozpadliny Wściekłego Ognia, zabij Taragamana Łaknącego i przynieś jego serce Neeru Płomiennemu Ostrzu w Orgrimmarze.', '', 'Wróć do Neeru Płomiennego Ostrza w Orgrimmarze.', '', '', '', '', 0),
(6384, 'koKR', 'Lot do Orgrimmaru', 'Za parę monet wiwerna zaniesie cię do Orgrimmaru. Kiedy tam dotrzesz, zanieś Mięsiwa Zargha Gryshce. Jej karczma jest w Dolinie Siły, niedaleko Podniebnej Wieży, gdzie wysadzi cię moja wiwerna.$B$BPorozmawiaj ze mną znowu, gdy będziesz $ggotów:gotowa; do drogi.', 'Wykup u mistrza wiwern Devraka lot wiwerną do Orgrimmaru, a potem zanieś Mięsiwa Zargha Gryshce w Orgrimmarze.', '', '', '', '', '', '', 0),
(6385, 'koKR', 'Doras, mistrz wiwern', 'Napisałam do Zargha list z podziękowaniami. Dostarczysz go dla mnie? Jeśli już $gbyłeś:byłaś; na Rozdrożu i $grozmawiałeś:rozmawiałaś; z tamtejszym mistrzem wiwern, możesz tam wrócić wiwerną.$B$BZanieś mój list Dorasowi, mistrzowi wiwern w Orgrimmarze, i porozmawiaj z nim o transporcie na Rozdroże.', 'Zanieś List Gryshki Dorasowi w Orgrimmarze.', '', '', '', '', '', '', 0),
(6386, 'koKR', 'Powrót na Rozdroże', 'Moje wiwerny są wyszkolone do lotów w wiele różnych miejsc, pod warunkiem że już tam $gbyłeś:byłaś; i $grozmawiałeś:rozmawiałaś; z tamtejszym mistrzem wiwern.$B$B$GByłeś:Byłaś; już na Rozdrożu i $grozmawiałeś:rozmawiałaś; z ich mistrzem wiwern, Devrakiem, więc teraz możesz polecieć stąd prosto do niego. Na Rozdrożu oddasz list Gryshki Zarghowi.$B$BPorozmawiaj ze mną, gdy będziesz $ggotów:gotowa; do drogi.', 'Wykup u mistrza wiwern Dorasa lot wiwerną na Rozdroże, a potem zanieś List Gryshki Zarghowi na Rozdrożu.', '', '', '', '', '', '', 0),
(6566, 'koKR', 'Co niesie wiatr', 'Dobrze znów cię widzieć, $N. Wiatr niesie wieści ze Wschodnich Królestw.$B$BSiadaj i słuchaj. $B', 'Wysłuchaj Thralla.', 'Opowieść Thralla', 'Wróć do Thralla w Orgrimmarze.', '', '', '', '', 0),
(6567, 'koKR', 'Czempion Hordy', 'Rexxar, jeden z moich najwierniejszych czempionów, odkrył drogę do leża smoczycy. Opuścił jednak Azeroth, by dołączyć do naszej wyprawy na Rubież.$b$bZostawił jednak tę wiedzę swojemu towarzyszowi, Rokarowi, w Wiosce Cienistej Ofiary. Masz go odszukać.', 'Odszukaj Rokara w Wiosce Cienistej Ofiary w Mrocznym Pustkowiu.', '', '', '', '', '', '', 0),
(6608, 'koKR', 'Ty za dobry.', 'Lumak już nie móc uczyć $N. Ty za $gdobry:dobra;! Ty szukać przyjaciel Lumaka, Nat Pagle. On człowiek, ale nie jeść! On przyjaciel Lumaka! Nat uczyć cię łowić bardziej dobrze.$B$BNat znaleźć na Pyłowym Bagnisku, na południe od miasta ludziów, Termorocośtamtakiego. Nat pewnie łowić ryby. Iść już!', 'Wydaje ci się, że Lumak próbuje ci powiedzieć, że nie może już pomóc ci w doskonaleniu umiejętności wędkowania. Może warto odszukać jego przyjaciela, Nata Pagle\'a – człowieka, który łowi ryby na jednej z wysp na południe od Theramore (tak przynajmniej $gzrozumiałeś:zrozumiałaś; słowa Lumaka).', '', '', '', '', '', '', 0),
(6611, 'koKR', 'Do Gadżetonu marsz!', 'Jak ty chcieć, żeby Zamja cię czegoś uczyć? Ty mieć już całe gotowanie mojo Zamji i dalej chcieć więcej!$B$BZamja nie pomóc. Ty grube musieć iść do Gadżetonu. Tam znaleźć mały goblin, nazywać się Dirge – on ci pomóc, tłusta ty kluseczko.$B$BJak zostać wielki kucharz w okolicy, to wrócić i uczyć Zamja, dobra? A teraz iść!', 'Udaj się do Gadżetonu na pustyni Tanaris i porozmawiaj z Dirge\'em Szybkosiekiem o dalszym rozwoju twojej kariery kucharskiej.', '', '', '', '', '', '', 0),
(6964, 'koKR', '', 'Prezenty, łakocie, podarunki... phi, powiadam!$B$BTe gobliny zatruwają prawdziwe znaczenie tego czasu – Zimowej Uczty. To czas odnowy; ziemia śpi pod kołdrą śniegu przyniesioną przez Praojca Mroza, który NIE jest tym niezdarnym błaznem w czerwonym stroju, o tam!$B$BJeśli chcesz się $gsam:sama; przekonać, o co naprawdę chodzi w Uczcie, zapytaj Sagorne\'a Graniokroka. Pewnie się zdziwi, że kogoś obchodzi historia, a nie prezenty.', 'Porozmawiaj z Sagorne\'em Graniokrokiem w Dolinie Mądrości w Orgrimmarze o Zimowej Uczcie.', '', '', '', '', '', '', 0),
(7061, 'koKR', '', 'Proszę – jeśli chcesz dowiedzieć się więcej o Zimowej Uczcie, przeczytaj tę księgę. Choć uważam, że to my właściwie pojmujemy tę legendę, dość długo zgłębiam legendy, by docenić zebranie wszystkich informacji w jednym źródle.$B$BGdy skończysz, zanieś księgę Kairnowi Krwawemu Kopytu do Gromowych Urwisk. Wiem na pewno, że chętnie usłyszy, że inni interesują się podaniami naszego ludu.', 'Możesz przeczytać księgę „Zimowa Uczta”, by dowiedzieć się więcej o tym święcie. Gdy skończysz, dostarcz ją Kairnowi Krwawemu Kopytu w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(7068, 'koKR', 'Fragmenty odłamka cienia', 'Silna magia być w świętym miejscu centaurów... w świętym miejscu Maraudon. Plemiona centaurów z Mrocznego Pustkowia bronić tego miejsca własnym życiem, ale nie móc nam przeszkodzić wziąć, czego potrzeba.$B$BTy, ty iść do tego Maraudonu i szukać kamienne stwory z odłamków cienia. Ty przynieść mi fioletowe kryształy, a Uthel\'nay zrobić ci coś za fatygę.$B$BTo miejsce być niebezpieczne, więc może ty wziąć paru przyjaciół.', 'Zbierz w Maraudonie 10 Fragmentów odłamka cienia i zanieś je Uthel\'nayowi w Orgrimmarze.', '', 'Wróć do Uthel\'naya w Orgrimmarze.', '', '', '', '', 0),
(7241, 'koKR', 'W obronie Mroźnych Wilków', 'Bębny wojny grzmią w dalekiej krainie, $N. Ulubiony klan twojego wodza został zaatakowany przez nikczemną Straż Gromdardy z Żelaznej Kuźni.$B$BPo twoim wyglądzie widzę, że jesteś $gzaprawiony:zaprawiona; w boju i $ggotów:gotowa; stanąć w obronie sprawy Mroźnych Wilków.$B$BTo ty musisz teraz zrobić kolejny krok na swojej drodze.$B$BNa północ od Smolnego Młyna, w Alterak, znajdziesz wejście do Doliny Alterak. Tam odszukasz Mistrza wojennego Laggronda. Pośpiesz się, $N, bo bitwa już się zaczęła!', 'Wyrusz do Doliny Alterak w Górach Alterak. Odszukaj Mistrza wojennego Laggronda, który stoi przed wejściem do tunelu, i porozmawiaj z nim, by rozpocząć służbę jako żołnierz Mroźnych Wilków. Dolinę Alterak znajdziesz na północ od Smolnego Młyna, u podnóża Gór Alterak.', '', '', '', '', '', '', 0),
(7341, 'koKR', 'Uczciwa wymiana', '', '', '', 'Wróć do Łowcy nagród Kolarka w Aszarze.', '', '', '', '', 0),
(7490, 'koKR', 'Zwycięstwo Hordy', 'Dokonano niemożliwego. Matka miotu Czarnego Stada leży martwa u twoich stóp. Weź jej głowę i złóż ją przed swoim wodzem.', 'Zanieś Głowę Onyxii Thrallowi w Orgrimmarze.', '', '', '', '', '', '', 0),
(7491, 'koKR', 'Na oczach wszystkich', 'Nadrządca Runthak czeka na ciebie w Dolinie Siły.$B$B<Thrall salutuje ci.>$B$BNie każ czekać swojej publiczności, $gbohaterze:bohaterko;.', 'Odszukaj Nadrządcę Runthaka w Dolinie Siły.', '', '', '', '', '', '', 0),
(7492, 'koKR', 'Obóz Mojache', 'Talo Cierniokopyt, starszy taurenów w Feralas, prosi o pomoc. Nie zdradził wielu szczegółów, ale powiedział, że potrzebuje zaufanych wysłanników do sprawy równie delikatnej... co groźnej.$B$BSłuż Hordzie, $N. Udaj się do Obozu Mojache w Feralas i porozmawiaj z Talo.', 'Porozmawiaj z Talo Cierniokopytem w Obozie Mojache w Feralas.', '', '', '', '', '', '', 0),
(7541, 'koKR', 'Służba Hordzie', '', '', '', '', '', '', '', '', 0),
(7660, 'koKR', 'Wymiana wilka – arktyczny wilk', '', '', '', 'Wróć do Ogunaro Wilczego Biegu w Aszarze.', '', '', '', '', 0),
(7661, 'koKR', 'Wymiana wilka – czerwony wilk', '', '', '', 'Wróć do Ogunaro Wilczego Biegu w Aszarze.', '', '', '', '', 0),
(7667, 'koKR', 'Wsparcie materialne', '$N, jest pewna pilna sprawa, w której mam nadzieję, że mi pomożesz... zarówno materialnie, jak i duchowo. Pozwól, że wyjaśnię.$B$BW głębi Scholomancjum w Lordaeronie jest komnata zwana Wielkim Ossuarium. Muszę ukończyć urządzenie, które przebije cienie tej okropnej sali. By dokończyć to, co zacząłem, potrzebuję dwóch diamentów: azerothiańskiego i nieskazitelnego czarnego. Wiem, że to nie byle drobiazgi – po prostu sam nie mam na nie środków.$B$BCzy $gmógłbyś:mogłabyś; dać mi po jednym z nich?', 'Jeśli chcesz pomóc Sagorne\'owi Graniokrokowi w Dolinie Mądrości w Orgrimmarze, przynieś mu Azerothiański diament i Nieskazitelny czarny diament.', '', 'Wróć do Sagorne\'a Graniokroka w Orgrimmarze.', '', '', '', '', 0),
(7732, 'koKR', 'Raport o Zukk\'ash', 'Podwójnie dobrze się $gspisałeś:spisałaś;, stawiając czoła zagrożeniu, jakie owady Zukk\'ash stanowią dla Obozu Mojache. To zagrożenie jeszcze długo nie minie, więc chciałbym poprosić cię o ostatnie zadanie w imieniu Hordy.$B$BTo dokument zawierający wszystko, czego dowiedzieliśmy się o owadach Zukk\'ash. Chcę, żebyś $gdostarczył:dostarczyła; go Zilzibinowi Bębnoznawcy do Dziury w Orgrimmarze. Zna się na obcych stworzeniach takich jak te; mam nadzieję, że zrobi coś z wiedzą, którą zdobyliśmy.', 'Dostarcz Raport z Obozu Mojache o Zukk\'ash Zilzibinowi Bębnoznawcy. Mieszka w Dziurze w Orgrimmarze.', '', '', '', '', '', '', 0),
(7783, 'koKR', '', 'Wraca dawne uczucie. Upragnione ukłucie zwycięstwa przenika całe twoje jestestwo. Przed tobą leży ogromna, pokryta bliznami bitew głowa Nefariana. Zanieś ją swojemu wodzowi, $gczempionie:czempionko;.', 'Zanieś Głowę Nefariana Thrallowi w Orgrimmarze.', '', '', '', '', '', '', 0),
(7784, 'koKR', '', 'Odszukaj Nadrządcę Runthaka w Dolinie Siły.', 'Porozmawiaj z Nadrządcą Runthakiem w Orgrimmarze. Czeka na ciebie w Dolinie Siły.', '', '', '', '', '', '', 0),
(7824, 'koKR', '', '', '', '', 'Wróć do Rashony Straglash w Durotarze.', '', '', '', '', 0),
