(9019, 'koKR', 'Ta klątwa spadła na nas zaledwie przez jeden medalion. Lord Valthalak z pewnością umie chować urazę.$B$BPostaramy się odnaleźć brakujące części – oby, zanim spotka mnie przedwczesna śmierć. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(9020, 'koKR', 'Ta klątwa spadła na nas zaledwie przez jeden medalion. Lord Valthalak z pewnością umie chować urazę.$B$BPostaramy się odnaleźć brakujące części – oby, zanim spotka mnie przedwczesna śmierć. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(9021, 'koKR', 'Ta klątwa spadła na nas zaledwie przez jeden medalion. Lord Valthalak z pewnością umie chować urazę.$B$BPostaramy się odnaleźć brakujące części – oby, zanim spotka mnie przedwczesna śmierć. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(9022, 'koKR', 'Ta klątwa spadła na nas zaledwie przez jeden medalion. Lord Valthalak z pewnością umie chować urazę.$B$BPostaramy się odnaleźć brakujące części – oby, zanim spotka mnie przedwczesna śmierć. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(9428, 'koKR', 'Ambasadorka uprzedziła mnie o twoim przybyciu, więc się ciebie spodziewałem.$B$BAmbasadorka chce po prostu, żebyś $gpomógł:pomogła; tu, ile tylko zdołasz. Wspominała coś o tym, że trzeba umocnić nasze stosunki z resztą Hordy.$B$BPopytaj – dalej w głębi posterunku są inni, którym przyda się pomoc. Słyszałem też, że na wybrzeżu, na samym zachodzie, jest jeszcze jedna placówka Hordy – Posterunek Zoram\'gar.', 0),
(9438, 'koKR', '<Widzisz, jak Thrallowi opada szczęka, gdy zaczyna czytać wiadomość od Nazgrela.>$B$BMój lud... musimy do nich dotrzeć. Musimy jak najszybciej dotrzeć do Nagrandu!', 0),
(9441, 'koKR', 'Wiele dla nas znaczy, że $gprzybyłeś:przybyłaś; nam z pomocą w godzinie potrzeby. Nieprędko zapomnimy ciebie i tego, który cię przysyła.$B$BDziękujemy ci.', 0),
(9626, 'koKR', '<Thrall zaczyna czytać list.>$B$BSylwana nie daje za wygraną. Przysłała więc jednego z czempionów samej Srebrnej Luny... ale co to właściwie zmienia?', 0),
(9627, 'koKR', 'Twoja praca ogromnie przysłużyła się sprawie naszej rasy. Thrall nie tylko wierzy, że potrafimy sami stawić czoła wrogowi, ale sądzi też, że dzięki naszej więzi z Rubieżą dotrze do swojego ludu.$B$BNie jest to do końca prawda, ale nie jest to też kłamstwo.$B$BPrzygotuj się na wielkie zmiany, $N. Oficjalnie jesteśmy teraz częścią Hordy.', 0),
(9813, 'koKR', '<Thrall zaczyna czytać list.>$b$bA więc krwawe elfy wreszcie uporały się ze swoim drobnym problemem. Nic dziwnego, że potrzebowały do tego twojej pomocy i całego pułku Porzuconych.$b$b<Wódz wybucha śmiechem.>$b$bChyba nie da się już tego powstrzymać. Koniec końców potrzebujemy ich tak samo, jak oni nas.', 0),
(10175, 'koKR', '<Głos Thralla staje się głuchy jak pomruk burzowej chmury.>Ja... Mam babkę? Ona żyje?', 0),
(10212, 'koKR', 'Jesteś $gprawdziwym bohaterem:prawdziwą bohaterką; Mag\'harów, $N. Gdyby nie ty, z pewnością zmiażdżyłyby nas ogry i Złamani.$B$BJesteśmy ubogim ludem, ale mamy kilka potężnych artefaktów. Proszę, nalegam, weź coś z naszego skarbca.', 0),
(10493, 'koKR', 'Ach, tak. Mux będzie bardzo zadowolony.$B$BTe karwasze były częścią większego zestawu pancerza. Jeśli zechcesz dalej mi pomagać, byłbym skłonny rozważyć rozstanie się z resztą.', 0),
(10495, 'koKR', 'Nasza umowa pozostaje w mocy. Pamiętaj tylko, że to zaledwie przedsmak tego, co cię czeka. Uwolnij mnie od tego przeklętego losu, a nagrodzę cię przedmiotami o naprawdę wielkiej mocy.', 0),
(10497, 'koKR', 'Ta klątwa spadła na nas zaledwie przez jeden medalion. Lord Valthalak z pewnością umie chować urazę.$B$BPostaramy się odnaleźć brakujące części – oby, zanim spotka mnie przedwczesna śmierć. Ale najpierw zajmijmy się twoją nagrodą.', 0),
(10499, 'koKR', 'Naprawdę będzie mi ciebie brakowało, $N. Mam wobec ciebie dług, którego mogę nigdy nie spłacić.$B$BNiech dobrze ci służy nowy pancerz na głowę i tors. Oby chronił cię przez długi czas i pomógł ci zdobyć jeszcze większą chwałę!', 0),
(10788, 'koKR', 'A więc światowy podróżnik raczył wrócić...$B$BMam nadzieję, że wyczuwasz sarkazm, $N, bo $gnarobiłeś:narobiłaś; mi sporo kłopotu, zmuszając mnie do wysłania wezwania. Pamiętaj, że od spopielenia dzieli cię włos strażnika Spaczenia, a oni nie mają włosów.$B$BSłuchaj uważnie, tej lekcji nie usłyszysz drugi raz.', 0),
(10789, 'koKR', 'Tak, widzę to w twoich oczodołach. Chcesz się uczyć dalej.$B$BDobrze więc, ta lekcja spodoba się każdemu z nas.', 0),
(10790, 'koKR', 'Łakniesz zakazanej wiedzy, tak? Mogę ci ją dać...', 0),
(10794, 'koKR', 'A więc chcesz pracować dla Strzaskanej Dłoni? Wygląda na to, że co dzień zjawia się ktoś nowy.$B$BSłuchaj uważnie, a wyjaśnię ci, co masz zrobić.', 0),
(12785, 'koKR', 'Ach, bardzo dobrze. Choroby, które nosi ta zgniła głowa, są śmiertelne, ale nie wolno nam cofać się przed niebezpieczeństwem ani przed tym, co budzi w nas odrazę. Pewnego dnia, $N, zrozumiesz, że potępienie jest drogą do zbawienia...', 0),
(12812, 'koKR', 'Ach, bardzo dobrze. Choroby, które nosi ta zgniła głowa, są śmiertelne, ale nie wolno nam cofać się przed niebezpieczeństwem ani przed tym, co budzi w nas odrazę. Pewnego dnia, $N, zrozumiesz, że potępienie jest drogą do zbawienia...', 0),
(13189, 'koKR', 'Eitrigg żyje dzięki temu paladynowi. Zostałby stracony, gdyby lord Fordring nie wyrwał go ze Stratholmu.$b$bTirion Fordring poświęcił wszystko, by ocalić życie orka... Znałem tylko jednego innego człowieka, który zdobył się na taką ofiarę.$b$b<Thrall powstrzymuje łzę.>$b$bZawsze będziesz w moim sercu, Taretho.$b$bTak. Za Tiriona Fordringa i za Eitrigga! Przyjmujemy cię w szeregi Hordy, a twój zakon – jako sojusznika.$b$bKrew i honor! Za Hordę!', 0),
(13257, 'koKR', 'Za tę zdradę odpowiadają władca demonów Varimathras i główny aptekarz Porzuconych, Putress.$b$b<Thrall kiwa głową.>$b$bTak, ten sam Putress, który odkrył lekarstwo na niedawny wybuch zarazy Plagi.$b$bCi, którzy nie stanęli po stronie ich reżimu, zostali straceni albo wygnani. Sylwana omal nie zginęła podczas przewrotu.$b$bHorda straciła Podmiasto. Orgrimmar przyjmie uchodźców z Porzuconych, dopóki ten kryzys nie zostanie rozwiązany. Na razie obowiązuje stan wojenny.', 0),
(13266, 'koKR', 'Wprowadzę cię w sytuację, $N.$b$bPodmiasto to strefa wojny. Aptekarze Putressa i demony Varimathrasa przejęli władzę. Okopali się w środku i używają przeciw naszym oddziałom tej przeklętej zarazy.', 0),
(14100, 'koKR', 'Ach, $gopanowałeś:opanowałaś; cztery totemy. Możesz być $gdumny:dumna; z tego, co dotąd $gosiągnąłeś:osiągnęłaś;, $N, ale to dopiero początek twojej wędrówki.$b$bProszę, przyjmij ten dar od Kręgu Ziemi. Noś tę relikwię przy sobie, a moc wszystkich czterech żywiołów będzie na twoje rozkazy.$b$bKontynuuj naukę, $gprzyjacielu:przyjaciółko;. Przed tym światem stoją poważne wyzwania – słyszę to w wietrze i czuję w pomrukach ziemi. Musimy być gotowi na najgorsze.', 0),
(24429, 'koKR', 'Przynosisz mi głowę kogoś, kto jest... Nie, lepiej się nad tym za bardzo nie zastanawiać. Bez wątpienia oczekujesz zapłaty za swoje bohaterskie czyny.', 0),
(25228, 'koKR', '<Torek przegląda zebrane przez ciebie zwoje.>$B$BKimkolwiek są ci ludzie, naprawdę chcą zdobyć zwolenników. I wygląda na to, że idzie im całkiem nieźle. Nie można pozwolić, by siali panikę i histerię wśród mieszkańców Orgrimmaru. Musimy zniechęcać do tej grupy i dowiedzieć się o niej jak najwięcej.', 0),
(25293, 'koKR', 'Więc ich $gznalazłeś:znalazłaś;? Dlaczego zaginieni mężczyźni i kobiety nie wrócili z tobą?$B$B<Opowiadasz strażnikowi krwi, co ci odpowiedzieli.>$B$BNie możemy zmusić ich, by zmienili zdanie i wrócili do rodzin. Dam znać rodzinom, że ich bliscy się odnaleźli i są bezpieczni. Kiedy rozbijemy ten kult, pewnie wrócą do normalnego życia.', 0),
(25347, 'koKR', '<Wręczasz strażnikowi krwi Torekowi urządzenia, które dała ci nadzorczyni, i wyjaśniasz plany kultu. Torek szeroko otwiera oczy.>$B$BTo Cho\'gall przewodzi kultowi? W takim razie nie ma wątpliwości, to sprawka Młota Zmierzchu! Nie tylko ciebie wysłali do miasta, by rozmieścić te urządzenia.', 0),
(25348, 'koKR', 'Doskonała robota, $N. Młot Zmierzchu zastanowi się dwa razy, zanim znów spróbuje obrócić przeciw nam naszych własnych ludzi. Pewnie nie tylko mnie martwi, jak wielu mieszkańców dało się nabrać na ich przesłanie. Czasy nie są łatwe, ale kto nie ma honoru ani lojalności, ten nie ma nic.', 0),
(25351, 'koKR', '<Wódz słucha, jak opowiadasz o swoim śledztwie w sprawie spisku Młota Zmierzchu, który miał zniszczyć Orgrimmar.>$B$BJesteś $goddanym członkiem:oddaną członkinią; Hordy, $N. Dobrze $gzrobiłeś:zrobiłaś;, przynosząc mi te wieści. Osobiście dopilnuję, by nasi wrogowie dostali to, na co zasłużyli!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(32, 'koKR', 'Wybacz, nie znam cię... ale sądząc po wszystkim, ty przynajmniej $gsłyszałeś:słyszałaś; coś o mnie. W czym mogę ci pomóc? Masz coś dla mnie?', 0),
(81, 'koKR', 'Jeśli nie $gprzyszedłeś:przyszłaś; nic kupić ani niczego dostarczyć, to marnujesz mój czas! Lepiej dla ciebie, jeśli masz ten sikacz!', 0),
(1145, 'koKR', 'Zazdroszczę ci, $N. Wyglądasz na kogoś, kto od dłuższego czasu przebywa poza murami Orgrimmaru.$B$BSam chętnie ruszyłbym w drogę w imieniu wodza, gdyby Thrall nie potrzebował moich umiejętności tu, w mieście. Ale dobrze nas prowadzi i ufam jego osądowi – zostanę tu tak długo, jak będę mu potrzebny.', 0),
(1146, 'koKR', 'Wojna przywiodła mnie i moich ludzi na Migoczące Równiny, $N. A co sprowadza ciebie?', 0),
(1262, 'koKR', 'Przybywasz z Paprotni na Pyłowym Bagnisku? Jak się miewa Nazeer i jak idą jego starania na mokradłach?', 0),
(1361, 'koKR', 'Widzę, że twoje zadanie nie zostało wykonane, $N. Czy mam powiadomić Sharlindrę o twojej nieudolności?', 0),
(1434, 'koKR', 'Pewien tauren, mój towarzysz, ostrzegł mnie, że satyry nie są tym, na co wyglądają. Uważa, że kryje się w nich coś więcej, że ich zło to wypaczenie ich prawdziwej natury. Ale ja niczego takiego nie widziałem.$B$BWidzę tylko bezlitosną rzeź słabych i zepsucie tych, którzy szukają mrocznej mocy.$B$BBędę dalej wypełniał swój obowiązek i tępił je, dopóki wódz nie rozkaże inaczej. Do tego czasu nie mam dla nich litości.', 0),
(1435, 'koKR', 'Starałem się, by ta magia była możliwie najprostsza. Wyciągnięcie ducha ofiary z jej zranionego ciała powinno być dziecinnie proste. Nie licz na to, że moc klejnotu całkiem dobije twojego wroga. Uaktywnij klejnot dopiero wtedy, gdy wróg będzie bliski śmierci, inaczej nic ci z niego nie przyjdzie.', 0),
(1501, 'koKR', 'Masz tabliczkę Vergi, $N? Jeśli nie, nie chcę z tobą rozmawiać, dopóki jej nie zdobędziesz.', 0),
(1504, 'koKR', 'Wędrowiec Pustki to potężne stworzenie. Pamiętam czasy, gdy to ja byłem na twoim miejscu, $N. Z biegiem lat mój własny wędrowiec Pustki coraz rzadziej ze mną walczy, choć podejrzewam, że to tylko dlatego, że liczy, iż opuszczę gardę.$B$BZapamiętaj to, $N.', 0),
(1512, 'koKR', '$GWróciłeś:Wróciłaś;. Jesteś $ggotów:gotowa; stoczyć walkę z sukkubem?', 0),
(1513, 'koKR', 'Gdy patrzę na sukkuba, serce mi wzlatuje... Ale zarazem niemal czuję, jak moja dusza odpływa niczym morze w czasie odpływu.$B$BUważaj, $gprzyjacielu:przyjaciółko;.', 0),
(1858, 'koKR', 'Czyż to nie irytujące, mieć przedmiot swojego pożądania w zasięgu ręki, a nie mieć sposobu, by się do niego dobrać?', 0),
(1944, 'koKR', 'Cieszę się, że $gwróciłeś:wróciłaś; w jednym kawałku, $N. Masz próbkę wody? Nie mogę się doczekać, aż zbadam jej właściwości.', 0),
(1945, 'koKR', 'Witaj, $N. Deino mówiła, że przyjdziesz i przyniesiesz włosy roześmianych sióstr. Masz je?', 0),
(1963, 'koKR', 'Głupcem jest ten, kto wierzy, że szarża z uniesionym toporem jest groźniejsza niż nóż w ciemności.', 0),
(2283, 'koKR', 'No, masz ten naszyjnik? Jak nie masz, to nie zobaczysz od nas ani miedziaka!', 0),
(2340, 'koKR', 'No proszę, kogo my tu mamy! Widzę, że wcale się nie $gspieszyłeś:spieszyłaś;. Miejmy nadzieję, że nie zmarnujesz mi czasu! Nie dostaniesz zapłaty, jeśli nie masz wszystkiego, o co prosiłem. I uwierz mi – wszystko sprawdzimy dwa i trzy razy!', 0),
(2478, 'koKR', 'Co masz do zameldowania, $N?', 0),
(2479, 'koKR', 'Cóż to???', 0),
(2751, 'koKR', 'Brązu, $N! Więcej brązu!!', 0),
(2752, 'koKR', 'Pokaż mi swoje oddanie.', 0),
(2753, 'koKR', 'Ich czaszki pękną pod naciskiem twoich butów!', 0),
(2754, 'koKR', 'Pokaż żelazu, kto tu rządzi, $N!', 0),
(2756, 'koKR', 'Aturk, jak czas, na nikogo nie czeka! Rusz się, ofermo!', 0),
(2950, 'koKR', 'Masz materiały, których potrzebuję? Bez wszystkiego, o co prosiłem, nie ulepszę tego projektu.', 0),
(2976, 'koKR', 'Pospiesz się, mam dziś wiele do zrobienia.', 0),
(3002, 'koKR', 'Co mi $gprzyniosłeś:przyniosłaś;?', 0),
(3504, 'koKR', 'Ach, Belgrom wreszcie zmądrzał i przysłał nam na pomoc kogoś spoza swoich szeregów, co?$b$bW tym obozie było kiedyś tuzin wojowników, $N, a teraz wszyscy nie żyją. Ta magini, Rimtori, wybiła ich co do jednego. Grała na Belgromie jak na lutni... nawet go uwiodła. To nie moja sprawa, ale między nami mówiąc, niezła z niej kusicielka. Pewnie dlatego wciąż tu siedzę i pomagam Belgromowi – sam pewnie dałbym się nabrać tak samo.', 0),
(3505, 'koKR', 'Tytuł księgi wytłoczono złotem na czarnej skórzanej okładce – Księga przywołań kaldorei. Gdy ją otwierasz, widzisz, że jest bardzo stara, ale w znakomitym stanie.$b$bZakładasz, że tekst jest w jakimś pradawnym języku... może kaldorei?$b$bInstynkt podpowiada ci, że trzeba będzie tu wrócić, gdy już wymierzysz krwawym elfom karę za zdradę.', 0),
(3506, 'koKR', 'Jak idzie rzeź zdradzieckich krwawych elfów, $N? Są jakieś postępy?$b$bMam nadzieję, że starczy ci siły, by rzucić tę żmiję na kolana! Za wszystko, co zrobiła, zasługuje tylko na bolesną śmierć!', 0),
(3507, 'koKR', 'Pamiętam cię. Prosiłem, żebyś $gposzedł:poszła; do Aszary i $gzniszczył:zniszczyła; tę dziewkę, która mnie zdradziła! Mam wrażenie, że to było wiele księżyców temu. Tylko nie mów mi, że Ag\'tor i pozostali też nie żyją!', 0),
(3541, 'koKR', 'No, czego trzeba, brachu? Mam dziś kupę spraw na głowie, a ciebie nie ma w moich planach. Będziesz mnie nękać, to dopilnuję, żeby się to zmieniło.', 0),
(3563, 'koKR', '$GRozmawiałeś:Rozmawiałaś; już z Jes\'rimonem?$B$BWśród trolli to straszny gbur, ale jego informacje zwykle są trafne, a zlecenia dobrze płatne.$B$BJeśli zniesiesz jego maniery, możesz nieźle zarobić na jego interesach.', 0),
(3923, 'koKR', 'Uważaj na głowę! Nie chcę, żeby mi przeszkadzała w pracy!', 0),
(3924, 'koKR', 'Masz instrukcję?', 0),
(4001, 'koKR', 'Co cię sprowadza w te czcigodne progi?', 0),
(4003, 'koKR', '<Księżniczka Moira kuli się ze strachu.>', 0),
(4300, 'koKR', 'Moi klienci nie są zbyt cierpliwi, $N. Masz już jakieś pazury?', 0),
(4509, 'koKR', 'To głupcy, $N! Nie przyjdzie im nawet do głowy rozejrzeć się za większym zagrożeniem; ich ślepa nienawiść do Przymierza nas zgubi. Nie wiem, jakich jeszcze dowodów zagrożenia ze strony silithidów mogę im dostarczyć – chyba że wrzucę ich do jednego z uli, żeby sami się przekonali!$B$BPrzepraszam, masz dla mnie jakieś wieści?', 0),
(4511, 'koKR', 'Zug zug! W czym mogę ci dziś pomóc?', 0),
(4941, 'koKR', 'Nie widzisz, że nie wolno mi przeszkadzać?', 0),
(4974, 'koKR', '<Thrall chrząka.>', 0),
(5301, 'koKR', 'Będę kuć stal, dopóki nie zabraknie mi tchu.', 0),
(5302, 'koKR', 'Za chwałę Hordy!', 0),
(5726, 'koKR', 'Masz już insygnia, $N?$b$bBędą niezbędne, byś $gmógł:mogła; przeniknąć do tego, co uważam za największe zagrożenie dla Hordy – i byśmy w końcu zaznali spokoju w naszym nowym domu.$b$bPrzekonasz się, jak zawiłą sieć potrafią utkać zarówno ludzie, jak i orkowie, gdy pcha ich chciwość i żądza władzy. Ukryte zamiary, zepsucie – wszystko stanie się jasne. Znajdziesz się w samym środku wojny, o której istnieniu $gnie miałeś:nie miałaś; pojęcia.', 0),
(5727, 'koKR', 'I jak, $N? Wierzy w nasz podstęp, czy sprawy mają się gorzej, niż z początku sądziłem?$b$bJeśli okażesz się $gcenny:cenna; dla Neeru, łatwiej nam będzie przeniknąć do Rady Cieni. Będzie miał mnóstwo informacji, dzięki którym wykurzymy tych, którzy chcą zniszczyć wszystko, co zbudowaliśmy w Durotarze.', 0),
(5728, 'koKR', '$GZnalazłeś:Znalazłaś; ich już, $N? Przywódców Palącego Ostrza.$b$bWiedziałem, że Rada Cieni chce odebrać mi Orgrimmar i całą Hordę, ale nie zdawałem sobie sprawy, jak szybko zdołali przeniknąć do miasta. Ta bestia ma tyle ramion... możemy je odcinać do upadłego, a i tak nie ruszymy się z miejsca. Będę musiał kazać moim szpiegom podwoić wysiłki.', 0),
(5761, 'koKR', '$GZabiłeś:Zabiłaś; bestię? To z pewnością przywódca Palącego Ostrza w Rozpadlinie Wściekłego Ognia.', 0),
(6384, 'koKR', 'Coś tu ładnie pachnie! Nie masz przypadkiem przy sobie surowego mięsa?', 0),
(6385, 'koKR', 'Potrzebujesz którejś z moich wiwern?', 0),
(6386, 'koKR', '$GWróciłeś:Wróciłaś; z Orgrimmaru? Smakowało Gryshce mięso, które jej posłałem?', 0),
(6566, 'koKR', 'Cierpliwości, $N. Słuchaj uważnie!', 0),
(7061, 'koKR', 'Witaj w Mulgorze i w naszej skromnej społeczności Gromowych Urwisk, $gprzyjacielu:przyjaciółko;. Zawsze interesuję się tymi, którzy postanawiają zainteresować się królestwem, jego ludem i jego podaniami. Czy to dlatego stoisz przede mną?', 0),
(7068, 'koKR', 'Ty znaleźć już kryształy? Rytuały mocy, zaklęcia wielkiej siły – te odłamki cienia może bardzo się przydać w różnej magii tajemnej.', 0),
(7341, 'koKR', 'Witaj. Jestem Kolark, łowca nagród z Gromowych Urwisk. Przemierzyłem wiele świata i wiele widziałem.$B$BPodróże po Południowych Morzach zaprowadziły mnie do odkrycia tych wspaniałych strzał z grotami z torium. Niestety, strzał mam bez końca, ale wyczerpał mi się zapas łusek. Phi, żaden szanujący się tauren nie dałby się przyłapać z lichym łukiem w ręku. Te strzały są bezużyteczne!$B$BProponuję wymianę: łuski z torium za moje strzały z grotami z torium, sztuka za sztukę. Umowa stoi?', 0),
(7490, 'koKR', '<Na widok olbrzymiej głowy Onyxii kamienny spokój Thralla znika na ułamek sekundy. Potężny Zgładziciel omal nie opuścił swojego miejsca.>', 0),
(7660, 'koKR', 'Jeśli przyprowadzisz mi swojego starego szybkiego wilka, wymienię go na jednego z nowego stada. Nowy wilk będzie tak samo szybki jak stary, tylko inaczej wygląda. Możesz obejrzeć szybkie wilki, które już mamy tu na wybiegu, żeby zobaczyć, jak będzie wyglądał.', 0),
(7661, 'koKR', 'Jeśli przyprowadzisz mi swojego starego szybkiego wilka, wymienię go na jednego z nowego stada. Nowy wilk będzie tak samo szybki jak stary, tylko inaczej wygląda. Możesz obejrzeć szybkie wilki, które już mamy tu na wybiegu, żeby zobaczyć, jak będzie wyglądał.', 0),
(7667, 'koKR', 'Głupio mi prosić o wsparcie materialne, ale moja wróżbiarska kula – urządzenie, które mam nadzieję ukończyć – wymaga po jednym z każdego. Jeśli nie możesz mi pomóc, oczywiście zrozumiem.', 0),
(7732, 'koKR', 'Witaj, $gprzyjacielu:przyjaciółko;... wyglądasz, jakby sprowadzała cię pilna sprawa. Mogę ci w czymś pomóc?', 0),
(7783, 'koKR', 'Żałuję, że nie mogłem tam być i zobaczyć pyska tej bestii, gdy $gzadawałeś:zadawałaś; śmiertelny cios, $N.', 0),
(7831, 'koKR', 'Kończą się nam zapasy tkaniny magów i przyda się twoja pomoc w ich uzupełnieniu! Licząc na całą społeczność, potrzebujemy od ciebie tylko 60 sztuk tkaniny magów, by osiągnąć nasz cel. Zapewniam cię, że Orgrimmar nie przeoczy takiej hojności!$B$BJeśli masz przy sobie sześćdziesiąt sztuk tkaniny magów i chcesz je przekazać, mogę je od ciebie przyjąć od razu.', 0),
(7835, 'koKR', 'Kończą się nam zapasy tkaniny magów i przyda się twoja pomoc w ich uzupełnieniu! Licząc na całą społeczność, potrzebujemy od ciebie tylko 60 sztuk tkaniny magów, by osiągnąć nasz cel. Zapewniam cię, że Trolle Mrocznej Włóczni nie przeoczą takiej hojności!$B$BJeśli masz przy sobie sześćdziesiąt sztuk tkaniny magów i chcesz je przekazać, mogę je od ciebie przyjąć od razu.', 0),
(7926, 'koKR', 'Tak, $gprzyjacielu:przyjaciółko;, w czym mogę pomóc? Masz może bon do wymiany?', 0),
(8258, 'koKR', 'Czas nagli, $N – czy $gzdołałeś:zdołałaś; powstrzymać Rycerza śmierci Mrocznego Łupieżcę?', 0),
(8485, 'koKR', 'Wódz przesyła ci pozdrowienia. Twoje czyny wzmacniają Hordę w tych niespokojnych czasach. A teraz – jaką masz do mnie sprawę?', 0),
(8913, 'koKR', '$GZdobyłeś:Zdobyłaś; to, czego potrzebuję, $N?', 0),
(8914, 'koKR', '$GZdobyłeś:Zdobyłaś; to, czego potrzebuję, $N?', 0),
(8915, 'koKR', '$GZdobyłeś:Zdobyłaś; to, czego potrzebuję, $N?', 0),
(8916, 'koKR', '$GZdobyłeś:Zdobyłaś; to, czego potrzebuję, $N?', 0),
(8917, 'koKR', '$GZdobyłeś:Zdobyłaś; to, czego potrzebuję, $N?', 0),
(8918, 'koKR', '$GZdobyłeś:Zdobyłaś; to, czego potrzebuję, $N?', 0),
(8919, 'koKR', '$GZdobyłeś:Zdobyłaś; to, czego potrzebuję, $N?', 0),
(8920, 'koKR', '$GZdobyłeś:Zdobyłaś; to, czego potrzebuję, $N?', 0),
(8923, 'koKR', 'Chcesz ze mną porozmawiać?', 0),
(8927, 'koKR', '$GGotów:Gotowa; do wymiany?', 0),
(8938, 'koKR', '$GGotów:Gotowa; do wymiany?', 0),
(8939, 'koKR', '$GGotów:Gotowa; do wymiany?', 0),
(8940, 'koKR', '$GGotów:Gotowa; do wymiany?', 0),
(8941, 'koKR', '$GGotów:Gotowa; do wymiany?', 0),
(8942, 'koKR', '$GGotów:Gotowa; do wymiany?', 0),
(8943, 'koKR', '$GGotów:Gotowa; do wymiany?', 0),
(8944, 'koKR', '$GGotów:Gotowa; do wymiany?', 0),
(8978, 'koKR', '$GWróciłeś:Wróciłaś; z urządzeniem?', 0),
(9011, 'koKR', 'Zgodnie z naszą umową – czy jesteś $ggotów:gotowa; oddać swoje części zestawu żywiołów w zamian za nowy Czepiec i Kamizelkę pięciu gromów?', 0),
(9016, 'koKR', '$GWróciłeś:Wróciłaś; i widzę w twoich oczach, że masz mi wiele do opowiedzenia, $N. Najpierw zajmijmy się twoją nagrodą.', 0),
(9017, 'koKR', '$GWróciłeś:Wróciłaś; i widzę w twoich oczach, że masz mi wiele do opowiedzenia, $N. Najpierw zajmijmy się twoją nagrodą.', 0),
(9018, 'koKR', '$GWróciłeś:Wróciłaś; i widzę w twoich oczach, że masz mi wiele do opowiedzenia, $N. Najpierw zajmijmy się twoją nagrodą.', 0),
(9019, 'koKR', '$GWróciłeś:Wróciłaś; i widzę w twoich oczach, że masz mi wiele do opowiedzenia, $N. Najpierw zajmijmy się twoją nagrodą.', 0),
(9020, 'koKR', '$GWróciłeś:Wróciłaś; i widzę w twoich oczach, że masz mi wiele do opowiedzenia, $N. Najpierw zajmijmy się twoją nagrodą.', 0),
(9021, 'koKR', '$GWróciłeś:Wróciłaś; i widzę w twoich oczach, że masz mi wiele do opowiedzenia, $N. Najpierw zajmijmy się twoją nagrodą.', 0),
(9022, 'koKR', '$GWróciłeś:Wróciłaś; i widzę w twoich oczach, że masz mi wiele do opowiedzenia, $N. Najpierw jednak zajmijmy się twoją nagrodą.', 0),
(9438, 'koKR', 'Przynosisz wieści z Rubieży, $N? Mów natychmiast!', 0),
(9626, 'koKR', 'Przychodzisz do mnie, $N? Mów, i to szybko. Nie mam czasu na ceregiele twojej rasy.', 0),
(9813, 'koKR', 'Tak, $N?', 0),
(10493, 'koKR', '$GZdobyłeś:Zdobyłaś; to, czego potrzebuję, $N?', 0),
(10495, 'koKR', '$GGotów:Gotowa; do wymiany?', 0),
(10497, 'koKR', '$GWróciłeś:Wróciłaś; i widzę w twoich oczach, że masz mi wiele do opowiedzenia, $N. Najpierw jednak zajmijmy się twoją nagrodą.', 0),
(12785, 'koKR', 'Witaj w Orgrimmarze, $n. Wielki aptekarz Putress uprzedził mnie o twoim przybyciu... masz ten zarażony mózg?', 0),
(12812, 'koKR', 'Witaj, $n. Przybywasz z Shattrath? Masz polecenia od wielkiego aptekarza Putressa?', 0),
(13189, 'koKR', 'Ciekawy obrót spraw.', 0),
(14100, 'koKR', 'Hmm, co cię sprowadza, że szukasz pomocy Kręgu Ziemi?', 0),
(24429, 'koKR', 'Co to ma znaczyć?!', 0),
(25228, 'koKR', 'No i co, $gdowiedziałeś:dowiedziałaś; się czegoś?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(2229, 0, 'koKR', 'Pomyśleć, że miejsce, gdzie wódz się urodził i dorastał, leży tak blisko.', 0),
(4047, 0, 'koKR', 'Duchy natury to potęgi, które należy szanować. Godnym udzielają wielkiej pomocy, a głupców karzą szybką śmiercią.', 0),
(4049, 0, 'koKR', 'Duch Szponogłazów płacze. Płacze od szczytów gór, przez rzeki, po ścięte, umierające drzewa.', 0),
(4485, 0, 'koKR', 'Dni się dłużą, a końca konfliktów w tych krainach wciąż nie widać. Nie trzeba być czarodziejem, żeby to wiedzieć. Chwyć za ostrze, póki możesz, $N. Wojna może zapukać do naszych drzwi w każdej chwili, a jeśli się nie mylę, wyglądasz na kogoś, kto się w niej lubuje.', 0),
(4498, 0, 'koKR', 'Witaj, $N.', 0),
(4791, 0, 'koKR', 'Może i nie toczymy otwartej wojny z Przymierzem, ale krew wciąż się między nami leje.', 0),
(5641, 0, 'koKR', 'Najgroźniejszym wrogiem, z którym Thrall chce się rozprawić, jest Płonące Ostrze – członkowie Hordy, którzy oddali swoją lojalność demonom. Chcą uprawiać swoją mroczną magię i niewiele ich obchodzi wizja Thralla dotycząca przyszłości Hordy tu, w Kalimdorze.', 0),
(6868, 0, 'koKR', 'Czego ci trzeba, $N? Mam nadzieję, że nie $gprzyszedłeś:przyszłaś; na to pustkowie tylko po to, żeby sobie pogadać.', 0),
(6986, 0, 'koKR', 'Nazywam się Dran Droffers, a to tutaj to mój głupi syn Malton. Jeśli potrzebujesz złomu albo chcesz jakiś sprzedać, to z nami trzeba gadać!', 0);
INSERT INTO `creature_template_locale` (`entry`, `locale`, `Name`, `Title`, `VerifiedBuild`) VALUES
(1383, 'koKR', 'Warkot', '', 0),
(2229, 'koKR', 'Krusk', '', 0),
(2391, 'koKR', 'Serge Hinott', '', 0),
(2704, 'koKR', 'Hanashi', '', 0),
(2855, 'koKR', 'Snang', '', 0),
(2857, 'koKR', 'Thund', '', 0),
(3057, 'koKR', 'Kairn Krwawe Kopyto', 'Wielki wódz', 0),
(3230, 'koKR', 'Nazgrel', 'Doradca Thralla', 0),
