INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1762, 'koKR', 'Tę demoniczną zbroję płytową nosiła istota, która jako pierwsza przeklęła nasz lud żądzą krwi. Dzięki bohaterskiemu czynowi jednego dzielnego orka została pokonana. Mannoroth Niszczyciel już nie istnieje. Niech ta zbroja zawsze nam przypomina, jak daleką drogę przeszliśmy i jak ciężko walczyliśmy, by odzyskać honor.$B$B– Thrall, wódz Hordy', 0),
(2511, 'koKR', 'Drogi Zarghu,$B$BSteki, które mi przysłałeś, są w porządku. Ładnie przerośnięte, grubo krojone i zapakowane w dziczy tłuszcz. Dokładnie takie, jakie lubię. Kiedy będę je później jadła, będę myśleć o tobie, obgryzając ostatnie kawałki kości i chrząstek. Zamknę oczy i zobaczę twoje silne, pokryte bliznami dłonie, jak siekają i kroją...$B$BHa! Przypomina mi się, jak miałeś ten wypadek i straciłeś palec... Och, Zarghu! Kiedy myślę o tamtym dniu, chichoczę jak mała dziewczynka.$B$BJesteś taki słodki, kiedy krwawisz!$B$B– Gryshka', 0),
(2661, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">STOPNIE WOJSKOWE HORDY I PRZYMIERZA</H1>\n<BR/>\n<BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRankHorde" align="left"/>\n<BR/>\n<P align="right">Throm\'ka! W tej</P>\n<P align="right">księdze znajdziesz</P>\n<P align="right">liczne spisy</P>\n<P align="right">stopni wojskowych</P>\n<P align="right">Hordy oraz</P>\n<P align="right">marnego Przymierza.</P>\n<P align="right">Najpierw będzie</P>\n<P align="right">Horda, potem Przymierze,</P>\n<P align="right">każde ze spisem stopni oficerskich, podoficerskich i szeregowych. Jak przystało, najsilniejsi są na górze, a słabsi pod nimi.</P>\n</BODY>\n</HTML>', 0),
(2664, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">PODOFICEROWIE I SZEREGOWI HORDY</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">Pierwszy sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">Starszy sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">Sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">Siepacz</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">Zwiadowca</P><BR/><BR/>\n</BODY>\n</HTML>', 0),
(2677, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">STOPNIE WOJSKOWE HORDY</H1><BR/>\n<P align="center">OFICEROWIE</P><BR/>\n<P align="center">Najwyższy wódz</P>\n<P align="center">Wódz</P>\n<P align="center">Generał</P>\n<P align="center">Generał porucznik</P>\n<P align="center">Czempion</P>\n<P align="center">Centurion</P>\n<P align="center">Legionista</P>\n<P align="center">Strażnik krwi</P>\n<P align="center">Kamienny strażnik</P><BR/>\n<P align="center">PODOFICEROWIE I SZEREGOWI</P><BR/>\n<P align="center">Pierwszy sierżant</P>\n<P align="center">Starszy sierżant</P>\n<P align="center">Sierżant</P>\n<P align="center">Siepacz</P>\n<P align="center">Zwiadowca</P><BR/>\n</BODY>\n</HTML>\n', 0),
(2857, 'koKR', '<HTML>\n<BODY>\n<H1 align="center">PODOFICEROWIE I SZEREGOWI PRZYMIERZA</H1><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\n<P align="right">Chorąży</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\n<P align="right">Starszy sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\n<P align="right">Sierżant</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\n<P align="right">Kapral</P><BR/><BR/>\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\n<P align="right">Szeregowy</P><BR/><BR/>\n</BODY>\n</HTML>', 0),
(2923, 'koKR', 'Szanowni przywódcy Hordy,$B$BZ wielką przyjemnością ja, Lor\'themar Theron, lord regent Quel\'Thalas, ogłaszam upadek dowódcy Plagi znanego nam jako Dar\'Khan Drathir.$B$BKrytycy rasy sin\'dorei wielokrotnie wytykali podczas dotychczasowych negocjacji przyczółek Dar\'Khana na naszych ziemiach. Mamy nadzieję, że to wydarzenie rozwiewa wszelkie wcześniejsze zastrzeżenia, jakie mogły żywić wasze dostojności.$B$B<Podpisano>Lor\'themar Theron', 0),
(2927, 'koKR', 'PS Nasz wielki magister otrzymał z Rubieży odpowiedź na pytanie Thralla. Odpowiedź brzmi: z całą pewnością tak.$B$B<List nosi dodatkowo pieczęć lady Sylwany Bieżywiatr>', 0),
(3539, 'koKR', 'Wodzu,$B$BPotężny wodzu, niech Światłość powstrzyma twą rękę i umocni twe serce. Wstrzymaj się z osądem nad tym upadłym czempionem – choćby na chwilę – i wysłuchaj moich słów.$B$BOddawca tego listu jest $gdawnym bohaterem:dawną bohaterką; Hordy. Choć od $gniego:niej; bije odór śmierci, a $gjego:jej; wygląd przywodzi na myśl Plagę, kryje w sobie duszę czempiona. Duszę, która dopiero niedawno połączyła się z ciałem.$B', 0),
(3540, 'koKR', '$N reprezentuje nowy, zjednoczony front przeciw Królowi Liszowi, zwany Rycerzami Hebanowego Miecza. Tak, wodzu, rycerze śmierci zwrócili się przeciw swemu dawnemu panu. Przewodzi im syn lorda Alexandrosa Mograine\'a – Spopielacza. Pragną tego, czego pragniemy my, czego pragniemy wszyscy: końca Plagi.$B$BNie proszę, byś przyjął $N i Rycerzy Hebanowego Miecza do Hordy, lecz jedynie, byś okazał wyrozumiałość.$B', 0),
(3541, 'koKR', 'Pamiętaj, Thrallu, że wszyscy służymy krwią i honorem.$B$BZ wyrazami szacunku$B$BNajwyższy lord Tirion Fordring$B$BPS Pozdrów ode mnie Eitrigga i przekaż mu, proszę, że w Północnej Grani przydałby mi się u boku dobry ork – rzecz jasna, za twoim pozwoleniem.$B', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(3753, 'koKR', 'Witaj na linii frontu, $N. Politycy mogą sobie knuć i spiskować między sobą, ale tutaj nie mają na to czasu. To Barykada, a my każdego dnia walczymy tu o przetrwanie.$B$BJeśli $gprzybyłeś:przybyłaś; tu w poszukiwaniu okazji, by wykazać się jako $gbohater:bohaterka;, znajdziesz ich mnóstwo... zwłaszcza teraz, gdy przemy w stronę Andorhalu i złowrogiej siły, która kieruje tam Plagą.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(5529, 'koKR', '', 'Słyszysz zew łowów, $N? Musisz uważnie nasłuchiwać, bo ten zew dobiega z głębi ciebie. Dobiega z głębi nas wszystkich.', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(8332, 'koKR', 'Thrall okazał wielką życzliwość, udzielając mi schronienia w swoich włościach. Tak czy inaczej, nie chcę nadużywać jego gościnności. Ściągnięcie kłopotów na naszego przywódcę byłoby dla mnie wielką hańbą.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(23128, 0, 0, 'koKR', 'Anu belore dela\'na!'),
(31649, 0, 0, 'koKR', 'Witaj, witaj! Bitwa o Podmiasto już trwa. Thrall walczy w środku, może uda ci się go znaleźć. Możesz też zaczekać na niego tutaj, wróci lada chwila.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1425, 'koKR', '', 'Duchy Gór Szponogłazów wciąż szaleją, $n.', 0),
(1426, 'koKR', '', 'Obawiam się, że może nam się nigdy nie udać ich ukoić...', 0),
(1610, 'koKR', 'Dobra, zaczynajmy.', '', 0),
(2085, 'koKR', 'To zajmie tylko chwilę, $n.', '', 0),
(2087, 'koKR', 'Wzywam cię twoim prawdziwym imieniem, Azrethocu. Ukaż mi swoje oblicze!', '', 0),
(2094, 'koKR', 'Ciekawy obrót spraw.', '', 0),
(2665, 'koKR', 'Teraz zabiorę się do szaty...', '', 0),
(2666, 'koKR', 'Twoja szata jest gotowa, $n.', '', 0),
(3077, 'koKR', 'Teraz musimy tylko wymyślić, jak to ustrojstwo znowu uruchomić.', '', 0),
(3078, 'koKR', 'Może ja to naprawię, tato. Daj, rzucę okiem.', '', 0),
(3079, 'koKR', 'Kanapkę? Co? Robisz mi kanapkę, tato?', '', 0),
(3080, 'koKR', 'Chłopcze, ty nawet kanapki byś nie zrobił, gdyby ci ktoś nie powiedział jak.', '', 0),
(3081, 'koKR', 'Malton, ty głąbie!', '', 0),
(3082, 'koKR', 'Pozwól, że przyniosę trochę wody do odczynnika atramentowego.', '', 0),
(3083, 'koKR', 'A teraz szybki rzut oka na te klejnoty.', '', 0),
(3084, 'koKR', 'To się świetnie nada. A teraz do rzeczy!', '', 0),
(3085, 'koKR', 'No i gotowe. Dziennik został dla ciebie przetłumaczony.', '', 0),
(3091, 'koKR', 'Tak jak myślałem, klejnoty i naszyjnik nie mają znaczenia. Chodzi wyłącznie o źródło mocy.', '', 0),
(3144, 'koKR', 'Zando\'zan ze Strzaskanej Dłoni. Jak Zando\'zan może ci pomóc? Nie może! Nie pomoże!\n', '', 0),
(3326, 'koKR', 'Ups!', '', 0),
(3945, 'koKR', 'Czego szukasz przy mojej kuźni? Nauki? A może chcesz poznać tajniki stali? Misteria kuźni? Mów śmiało, $gsiepaczu:siepaczko;!', '', 0),
(3983, 'koKR', 'O co chodzi? Nie widzisz, że jestem zajęty?', '', 0),
(3987, 'koKR', '', 'Nie szkolę kowali bez umiejętności. Wróć, kiedy będziesz mieć coś porządnego do pokazania.', 0),
(4558, 'koKR', 'Siepacze! Do ataku!', 'Siepacze! Do ataku!', 0),
(4617, 'koKR', 'Nie licząc siepaczy przed wejściem, ja i moi bracia walczyliśmy w bitwie o Hyjal. Każdy, kto zechce okraść bank, najpierw musi zmierzyć się z nami.', 'Nie licząc siepaczy przed wejściem, ja i moi bracia walczyliśmy w bitwie o Hyjal. Każdy, kto zechce okraść bank, najpierw musi zmierzyć się z nami.', 0),
(4619, 'koKR', 'Własną krwią ręczę za bezpieczeństwo tego banku. Wystarczy ci to?', 'Własną krwią ręczę za bezpieczeństwo tego banku. Wystarczy ci to?', 0),
(4621, 'koKR', 'Wolisz powierzyć swoje dobra goblinowi?', 'Wolisz powierzyć swoje dobra goblinowi?', 0),
(4622, 'koKR', 'Tyle lat walki i niewoli... Dobrze znów mieć dom.', 'Tyle lat walki i niewoli... Dobrze znów mieć dom.', 0),
(4623, 'koKR', 'Mów, czego chcesz, i to szybko.', 'Mów, czego chcesz, i to szybko.', 0),
(4630, 'koKR', 'Nawet w czasie pokoju trwa wojna, a wiele klanów wciąż walczy pod sztandarem wodza. Czy przybywasz, by dołączyć swój klan do tych, którzy walczą za Orgrimmar?', 'Nawet w czasie pokoju trwa wojna, a wiele klanów wciąż walczy pod sztandarem wodza. Czy przybywasz, by dołączyć swój klan do tych, którzy walczą za Orgrimmar?', 0),
(4635, 'koKR', 'Ziemia skrywa wiele tajemnic, $N. Naszym obowiązkiem jest dopilnować, by te, które dla dobra wszystkich muszą pozostać tajemnicą, takimi pozostały.', '', 0),
(4730, 'koKR', '', '...ups.', 0),
(4757, 'koKR', 'Obrońca poległ!', '', 0),
(4792, 'koKR', 'Mamy swoje obowiązki, $N. Obowiązki wobec Hordy.', '', 0),
(4793, 'koKR', 'Gdzie jest wódz Krom\'zar?', 'Gdzie jest wódz Krom\'zar?', 0),
(4926, 'koKR', 'Uważaj, $n! Spójrz na zachód!', '', 0),
(5182, 'koKR', 'Witam cię ciepło, podobnie jak Strzaskana Dłoń.$B$BNie rób takiej zdziwionej miny, $n. Nawet na najwyższych grzędach Orgrimmaru są cienie – coś musi się w nich kryć. Strzaskana Dłoń chętnie bierze tę rolę na siebie. Thrall, choć ma dobre serce, przyznaje, że Dłoń jest potrzebna, by orkowie i trolle byli bezpieczni.$B$BAle nie po to tu jesteś, żeby gadać o moich interesach, przychodzisz po coś innego.', '', 0),
(5184, 'koKR', 'Gdzie jest Krater Un\'Goro?', 'Gdzie jest Krater Un\'Goro?', 0),
(5742, 'koKR', 'Warkot nazywa mnie tępakiem, bo za wolno robię. A ja po prostu chcę dobrze wykonać robotę, a to wymaga czasu.', '', 0),
(5795, 'koKR', 'Jeśli wykażę się przed Saru, nie będzie miał wyjścia i pozwoli mi walczyć o rękę jednej ze swoich córek. Wtedy zobaczymy, kto będzie szydził.', '', 0),
(5796, 'koKR', 'Trzymaj się z dala od Sumi i Tumi. One są... zajęte.', '', 0),
(5922, 'koKR', 'Posłuchaj opowieści starszego, $n. Mam ich wiele do opowiedzenia...', '', 0),
(6013, 'koKR', 'Oddajcie cześć swoim bohaterom! Tego dnia zadali potężny cios jednemu z naszych najbardziej znienawidzonych wrogów! Fałszywy wódz, Rwij Czarnoręki, poległ!', '', 0),
(6014, 'koKR', 'Skąpcie się w mojej mocy! Pijcie moją potęgę! Walczcie ku chwale Hordy!', '', 0),
(6440, 'koKR', 'Zug zug, $gdzielny śmiałku:dzielna śmiałkini;! Mam dla ciebie do obejrzenia najlepiej hodowane wilki wierzchowe. Nigdzie nie znajdziesz zwierzęcia o takiej wytrzymałości i takim instynkcie przetrwania jak wilk! Proszę, przyjrzyj się im.', 'Zug zug, $gdzielny śmiałku:dzielna śmiałkini;! Mam dla ciebie do obejrzenia najlepiej hodowane wilki wierzchowe. Nigdzie nie znajdziesz zwierzęcia o takiej wytrzymałości i takim instynkcie przetrwania jak wilk! Proszę, przyjrzyj się im.', 0),
(6489, 'koKR', 'Jestem Krathok, nadzorca tych rzemieślników.', '', 0),
(6500, 'koKR', 'Witaj, $N!', '', 0),
(7218, 'koKR', 'Wszyscy członkowie Hordy są w moich oczach równi, $n. Wszyscy dźwigaliśmy wiele brzemion i gdyby nie mądrość i honor, nie bylibyśmy lepsi od Plagi ani od mojego ludu z czasów, gdy naszą krew skaził demon Mannoroth.$B$BTwoim obowiązkiem jest wspierać Hordę i bronić naszego sposobu życia. Ale twoim obowiązkiem jest też wiedzieć, kiedy okazać łaskę i współczucie – zarówno przyjacielowi, jak i wrogowi.$B$BZrozum to dobrze. To jest nowa Horda, a nie jakaś zrodzona z demonów armia pozbawiona wolnej woli.', '', 0),
(7536, 'koKR', 'Mogę nauczyć cię tajników jazdy na wilku, o ile masz dość złota, by zapłacić za lekcję!', 'Mogę nauczyć cię tajników jazdy na wilku, o ile masz dość złota, by zapłacić za lekcję!', 0),
(7701, 'koKR', 'Wszystkie butelki na tym stole to mikstury, które dziś uwarzyłem. A mówią, że pilnowany garnek nigdy nie kipi. Ha!', '', 0),
(7733, 'koKR', 'Jestem zajęty, $n. Powiedz Whuutowi, żeby się tym zajął, cokolwiek to jest. Ten szczeniak cały dzień kipi ze złości. Jeszcze trochę, a coś sobie zrobi.', '', 0),
(7748, 'koKR', 'Znowu ktoś przeszkadza. Jak mam cokolwiek zrobić w takich warunkach? Nie odpowiadaj; czy wyglądam, jakby obchodziło mnie, co masz do powiedzenia? Jeśli mamy kiedyś posprzątać to miejsce i poszerzyć nasze imperium, potrzebuję absolutnej ciszy!', '', 0),
(7820, 'koKR', 'Kto mówi, że orkowie nie są bystrzy? Żeby być inżynierem, trzeba mieć sporo w głowie!', '', 0),
(7856, 'koKR', 'Czasem nawet ja sam siebie zaskakuję!', '', 0),
(7886, 'koKR', 'Throm-ka! Czego szukasz, $gnieznajomy:nieznajoma;?', '', 0),
(7927, 'koKR', 'Niektórzy poszukiwacze przygód myślą, że zaklinanie nie działa. Kiedy wyzywam ich na pojedynek, szybko zmieniają śpiewkę!', '', 0),
(7961, 'koKR', '', 'Podoba ci się dywanik? Sama zabiłam tę bestię i zdjęłam z niej skórę. Oby wszystkie centaury padały równie łatwo.', 0),
(8019, 'koKR', 'Czy jestem zajęty? Co to ma znaczyć? Myślisz, że stoję tu cały dzień i kręcę młynka palcami? Jeśli chcesz coś kupić, pogadaj z Handorem.', '', 0),
(8071, 'koKR', 'W naszych wyrobach używamy wielu zwierzęcych futer i skór.', '', 0),
(8086, 'koKR', 'Hej, co mogę dla ciebie zrobić?', '', 0),
(8111, 'koKR', 'Moje wiwerny są wyszkolone, by szybko przelatywać przez gorące powietrze Pustkowi.', '', 0),
(8120, 'koKR', 'Rzuć okiem na moje mięsa, $gprzyjacielu:przyjaciółko;. Chyba nie wybierzesz się na Pustkowia bez porządnego zapasu prowiantu.', '', 0),
(8122, 'koKR', 'Kto nie spojrzał na świat z grzbietu wiwerny, ten nie żył.', '', 0),
(8147, 'koKR', 'Sporo z tego, co widzisz w sklepie, zrobiłem sam. Co o tym myślisz? Zastanów się nad odpowiedzią, może od niej zależeć twoje życie.', '', 0),
(8229, 'koKR', 'Co możesz mi powiedzieć o niedźwiedziu Ursangousie?\n', 'Co możesz mi powiedzieć o niedźwiedziu Ursangousie?', 0),
(8230, 'koKR', 'Co możesz mi powiedzieć o nocnej szablobestii Shadumbrze?\n', 'Co możesz mi powiedzieć o nocnej szablobestii Shadumbrze?', 0),
(8231, 'koKR', 'Co możesz mi powiedzieć o hipogryfie Ostroszponie?\n', 'Co możesz mi powiedzieć o hipogryfie Ostroszponie?', 0),
(8232, 'koKR', '', 'Ten niedźwiedź krąży szlakiem niedaleko Ścieżki Głębokiego Szponu, na zachód od Jeziora Mystral i placówki Przymierza, Schronienia Srebrnego Wiatru. Choć to najłatwiejsza z trzech bestii, z którymi zmierzysz się podczas Łowów w Jesionowej Kniei, nie wolno go lekceważyć. Stale zagraża podróżnym wędrującym między Jesionową Knieją a Górami Szponogłazami.', 0),
(8233, 'koKR', '', 'Podobno ta nocna szablobestia łagodnieje w obecności nocnych elfów i ich sojuszników, co czyni ją tym godniejszym przeciwnikiem. Łowiecki szlak Shadumbry wiedzie od Ustronia Raynewood na zachód od nas, aż po ziemie leżące dalej na zachód. Jej futro ma barwę smoły, a jej szybkości nie wolno nie doceniać.', 0),
(8234, 'koKR', '', 'Najpotężniejszą z bestii Łowów w Jesionowej Kniei, Ostroszpona, samozwańczy strażnicy tej krainy – nocne elfy – puszczają wolno. Ostroszpon wypatruje ofiar na południe stąd i z lubością rozszarpuje na strzępy niczego niepodejrzewających podróżnych.$B$BPowalenie takiej bestii byłoby najwspanialszą zdobyczą, $n. Życzę ci powodzenia w łowach na tego stwora!', 0),
(8308, 'koKR', 'Proszę, podziel się ze mną swoją mądrością, wodzu.', 'Proszę, podziel się ze mną swoją mądrością, wodzu.', 0),
(8309, 'koKR', 'Strzaskanej Dłoni udało się rozmieścić szpiegów w całej górnej cytadeli Czarnej Góry. Choć zbieranie informacji idzie powoli, dokonaliśmy odkryć, których nie można zignorować.', '', 0),
(8310, 'koKR', 'Jakich odkryć?', 'Jakich odkryć?', 0),
(8311, 'koKR', 'Wygląda na to, że wpływy Czarnego Stada sięgnęły poza granice Płonących Stepów, aż do samego królestwa Wichrogrodu! Uzurpatorka została już zdemaskowana i przepędzona.', '', 0),
(8312, 'koKR', 'Uzurpatorka?', 'Uzurpatorka?', 0),
(8313, 'koKR', 'Owszem. Matka miotu Czarnego Stada za pomocą iluzji i podstępu podszywała się pod członkinię królewskiego dworu. Co gorsza, przejęła kontrolę nad obecnym najwyższym lordem Wichrogrodu, Bolvarem Fordragonem.$B$BNic dziwnego, że zapadały tam tak nierozsądne decyzje wojskowe. Ostatnie ruchy wojsk Przymierza zbijały nas z tropu. Teraz rozumiemy, że Czarne Stado próbowało podzielić to imperium – zniszczyć je od środka.', '', 0),
(8314, 'koKR', 'Z całym szacunkiem, wodzu – czemu nie pozwolić, by zostali zniszczeni? Czy to nie wzmocniłoby naszej pozycji?\n', 'Z całym szacunkiem, wodzu – czemu nie pozwolić, by zostali zniszczeni? Czy to nie wzmocniłoby naszej pozycji?\n', 0),
(8315, 'koKR', '<Thrall się śmieje.>$B$BTyle jeszcze musisz się nauczyć, $N.$B$BJesteś zbyt $gmłody:młoda;, by pamiętać wojny i rozlew krwi minionych wieków. Zbyt $gmłody:młoda;, by pamiętać brzemię klątwy, którą niósł nasz lud.$B$BNasze stosunki z Przymierzem są w tej chwili kruche. Zdarzają się potyczki i mniejsze bitwy, ale panuje pokój – coś, czego nasz lud nie zaznał od tysiącleci. Czy $goddałbyś:oddałabyś; to i $grzucił:rzuciła; nas znów w paszczę chaosu, tym razem przeciw nowemu wrogowi? Takiemu, który nie spocznie, dopóki nie zniszczy nas wszystkich?', '', 0),
(8316, 'koKR', 'Ja... Nie $gpomyślałem:pomyślałam; o tym w ten sposób, wodzu.', 'Ja... Nie $gpomyślałem:pomyślałam; o tym w ten sposób, wodzu.', 0),
(8317, 'koKR', 'Nie, $n, nie $gpomyślałeś:pomyślałaś;. Nie winię cię jednak, bo masz umysł podobny do mojego z czasów młodości: porywczy, buntowniczy i często pozbawiony choćby jednej spójnej myśli! Na takie cechy nie mogę już sobie pozwolić.$B$BDość narzekania. $N, mam dla ciebie zadanie – takie, którego możesz nie przeżyć.', '', 0),
(8318, 'koKR', 'Żyję tylko po to, by służyć, wodzu! Bez twojego przewodnictwa moje życie jest puste i bez sensu.', 'Żyję tylko po to, by służyć, wodzu! Bez twojego przewodnictwa moje życie jest puste i bez sensu.', 0),
(8319, 'koKR', '<Thrall się śmieje.>$B$BZapamiętam... A teraz uważaj, $n. Matka miotu Czarnego Stada, Onyxia, została wykurzona ze swojej pozycji w Wichrogrodzie. Uciekła do swojego leża na Pyłowym Bagnisku.$B$BNie możemy pozwolić, by żyła tak blisko naszych stolic. Musimy uderzyć pierwsi, zanim to ona uderzy w nas!$B$BChcę jej śmierci, $n.', '', 0),
(8320, 'koKR', 'Oczywiście, wodzu!', 'Oczywiście, wodzu!', 0),
(8334, 'koKR', 'Ryba taka pyszna. Ty chcieć uczyć się ryba? Jeść ryba? Mmmmm...', '', 0),
(8335, 'koKR', 'Potrzebuję szkolenia, Lumaku.', 'Potrzebuję szkolenia, Lumaku.', 0),
(8346, 'koKR', '', 'Czy Zamja może ci pomóc, $N?', 0),
(8347, 'koKR', 'Potrzebuję szkolenia, Zamjo.', 'Potrzebuję szkolenia, Zamjo.', 0),
(8414, 'koKR', 'Swoje wierzchowce udostępniam tylko tym, których Orgrimmar i rasa orków darzą najwyższym poważaniem. Idź i wykaż się przed nami, a wtedy pozwolę ci obejrzeć moje potężne wilki.', 'Swoje wierzchowce udostępniam tylko tym, których Orgrimmar i rasa orków darzą najwyższym poważaniem. Idź i wykaż się przed nami, a wtedy pozwolę ci obejrzeć moje potężne wilki.', 0),
(8436, 'koKR', 'Nauczę cię jazdy wierzchem dopiero wtedy, gdy orkowie z Orgrimmaru obdarzą cię najwyższym poważaniem, $N.', 'Nauczę cię jazdy wierzchem dopiero wtedy, gdy orkowie z Orgrimmaru obdarzą cię najwyższym poważaniem, $N.', 0),
(8810, 'koKR', 'Chcesz się nauczyć władać nową bronią, czy tylko marnujesz mój czas?', '', 0),
(8813, 'koKR', 'Mów, jakiej broni chcesz się nauczyć, albo się wynoś.', '', 0),
(8862, 'koKR', 'Hej, hej. To dobre miejsce, żeby nauczyć się władać nową bronią.', '', 0),
(8864, 'koKR', 'Czego chcesz się nauczyć?', '', 0),
(9000, 'koKR', 'Odpowiadam za rekrutację do Klanu Mroźnego Wilka. Jako żołnierz Mroźnych Wilków masz obowiązek meldować się u mnie w miarę, jak rośnie twoja ranga w klanie.$B$BHonor i szacunek zdobywa się na tym mroźnym polu.', '', 0),
(9013, 'koKR', 'Witaj, $N. Jestem Rokaro.', '', 0),
(9014, 'koKR', 'Rokaro, $gzgubiłem:zgubiłam; Amulet smoczego ognia. Czy da się stworzyć nowy?', 'Rokaro, $gzgubiłem:zgubiłam; Amulet smoczego ognia. Czy da się stworzyć nowy?', 0),
(9491, 'koKR', 'Ludu Hordy, mieszkańcy Orgrimmaru, zbierzcie się i oddajcie cześć bohaterowi Hordy! Tego dnia $n, pod egidą naszego wspaniałego wodza, $gzadał:zadała; śmiertelny cios Czarnemu Stadu. Matka miotu, Onyxia, nie żyje!', '', 0),
(9492, 'koKR', 'Bądźcie świadkami niezaprzeczalnej potęgi waszego wodza! Niech porwie was bojowy okrzyk pogromców smoków!', '', 0),
(9494, 'koKR', 'Jestem tym, który bez pytań wykonuje rozkazy wodza. Jestem Hordą.', '', 0),
(9667, 'koKR', 'Witaj w Gromowych Urwiskach, $gmłodzieńcze:dziewczyno;. Znajdziesz tu bezpieczne schronienie przed troskami świata. Wszyscy członkowie Hordy są tu mile widziani.$B$BW tym świętym miejscu ożywają duchy teraźniejszości i przeszłości, $gprzyjacielu:przyjaciółko;. Oddawaj im cześć, a tym samym oddasz cześć sobie.', '', 0),
(9670, 'koKR', 'Wodzu Krwawe Kopyto, to może zabrzmieć dziwnie... ale mam pod opieką chłopca, który jest bardzo nieśmiały. Jesteś dla niego bohaterem, a on poprosił mnie, żebym $gzdobył:zdobyła; odcisk twojego kopyta.', 'Wodzu Krwawe Kopyto, to może zabrzmieć dziwnie... ale mam pod opieką chłopca, który jest bardzo nieśmiały. Jesteś dla niego bohaterem, a on poprosił mnie, żebym $gzdobył:zdobyła; odcisk twojego kopyta.', 0),
(9671, 'koKR', 'Ach, bez wątpienia przyszły wojownik! Rozumiem, że bierzesz udział w Tygodniu Dziecka, tak? Ogrzewa to moje zmęczone kości, gdy słyszę, że dajesz przykład, za którym inni z pewnością pójdą.$B$BZ przyjemnością spełnię prośbę twoją i chłopca. Hmm... jaką radę mam mu dać? Słuchaj duchów, tak... może też coś o tym, żeby zjadał wszystkie warzywa...', '', 0),
(9693, 'koKR', '', 'Teraz należycie do mnie, dzieci. Wyrośniecie na silną część Hordy!', 0),
(9694, 'koKR', '', 'Przestańcie jęczeć!', 0),
(9695, 'koKR', '', 'Posprzątajcie tu! Nie będziemy żyć w takim chlewie.', 0),
(9696, 'koKR', '', 'Albo będzie po mojemu, albo wynocha na Złotą Drogę. Zrozumiano?', 0),
(9867, 'koKR', 'NEFARIAN ZGINĄŁ! Ludu Orgrimmaru, pokłoń się przed potęgą $n i $gjego:jej; sojuszników, bo zadali Czarnemu Stadu cios, który z pewnością wyrwie Aspekty z ich marazmu! Tę klęskę na pewno odczuje ojciec Czarnego Stada: Śmiercioskrzydły wije się dziś w bólu i udręce!', '', 0),
(9868, 'koKR', 'Niech porwie was wyczyn, którego $gdokonał:dokonała; $n! Radujcie się $gjego:jej; bojowym okrzykiem!', '', 0),
(9869, 'koKR', 'Spójrz na tego poległego smoka, $N. Potęga Hordy jest niepodważalna!', '', 0),
(9889, 'koKR', '', 'Hej, ty tam! Jeśli chcesz zdobyć szacunek Mrocznej Włóczni, możesz zacząć od przekazania cennych zasobów dla potrzebujących! Tkaniny i bandaże nie rosną na drzewach, wiesz?$B$BZamiast spieniężać różne kawałki tkanin, które znajdujesz podczas przygód, oddaj je nam! W ten sposób zyskasz uznanie Mrocznej Włóczni!', 0),
(9890, 'koKR', '', 'W tych trudnych czasach zwykły datek z tkanin może bardzo pomóc tym, którym powodzi się gorzej niż nam. Z tkanin powstają ubrania i bandaże – jedne i drugie są ważne dla wysiłku wojennego!$B$BJeśli chcesz przekazać tkaniny orkom z Orgrimmaru, chętnie je przyjmę i dopilnuję, byś $gotrzymał:otrzymała; za to należne uznanie.$B$BZa Hordę!', 0),
(10097, 'koKR', 'Festyn Lunomroku zawita do miasta! Nie przegap go!', '', 0),
(10098, 'koKR', 'Festyn Lunomroku nadciąga! Zabawa dla dzieci w KAŻDYM wieku! Zapraszamy wszystkich!', '', 0),
(10099, 'koKR', 'Podejdźcie bliżej i posłuchajcie o najwspanialszym widowisku w całym Azeroth – Festynie Lunomroku! Hura!', '', 0),
(10100, 'koKR', 'Nie przegapcie żadnego z niesamowitych widoków i cudów Festynu Lunomroku, gdy zawita do miasta!', '', 0),
(10109, 'koKR', 'Gdzie rozstawi się Festyn Lunomroku, kiedy przyjedzie?', 'Gdzie rozstawi się Festyn Lunomroku, kiedy przyjedzie?', 0),
(10115, 'koKR', 'Gdy Festyn Lunomroku zostanie otwarty, będzie w Mulgorze. Rozbijemy namioty na południowy zachód od Gromowych Urwisk!', '', 0),
(10173, 'koKR', 'Musimy za wszelką cenę zapewnić przetrwanie tego obozu, $N! Nie wolno okazywać wrogom żadnej litości, bo oni z pewnością nie okazaliby jej nam, gdybyśmy jej potrzebowali.', '', 0),
(10174, 'koKR', 'Nastały niebezpieczne czasy, $N. Budzi się pradawne zło, a jemu wszystko jedno, czy należysz do Hordy, czy do Przymierza.', '', 0),
(10863, 'koKR', 'Nadeszła wojna, $n. Czas, by każdy członek Hordy odpowiedział na wezwanie i stanął do walki z tchórzliwym Przymierzem.', '', 0),
(12331, 'koKR', '', 'Atak Plagi na mój dwór został odparty. Możecie wrócić do swoich zajęć.', 0),
(13466, 'koKR', '', 'Witaj, $N! Ufam, że dzień ci sprzyja?', 0),
(13472, 'koKR', 'Witaj. Ufam, że dzień ci sprzyja?', '', 0),
(13505, 'koKR', 'Jesteś tu mile $gwidziany:widziana;, $N. Przynajmniej na razie.', '', 0),
(15206, 'koKR', 'Bądź $gsilny:silna;. Kael\'thas nas zdradził i wszystko, co znamy, się chwieje, ale nie trać ducha. Przetrwamy, jak zawsze. Arthas nie złamał naszego ducha, gdy przetoczył się przez nasze ziemie, i Kael\'thasowi też się to nie uda. Niech to będzie dla nas wszystkich nauka na drodze ku pomyślnej przyszłości.', '', 0),
(15769, 'koKR', '', 'Witaj, $gmłodzieńcze:dziewczyno;.', 0),
(15770, 'koKR', 'Witaj, Wszechmatko. Garosz powiedział mi, że chcesz ze mną mówić.', 'Witaj, Wszechmatko. Garosz powiedział mi, że chcesz ze mną mówić.', 0),
(15771, 'koKR', '', 'Witaj, $gmój drogi:moja droga;. Jestem Geyah, matrona Mag\'harów.$B$B<Wszechmatka Geyah kaszle.>$B$BSkoro tu jesteś, można bezpiecznie założyć, że portal się otworzył. Większość tutejszych orków była zbyt młoda albo zbyt chora, by pamiętać Mroczny Portal.$B$B<Wszechmatka Geyah wskazuje orków wokół siebie.>$B$BWielu z nich było sierotami albo wkrótce miało nimi zostać. O tak, Czarnoręki nie chciał inaczej. Oddzielić chorych od zdrowych. Przetrwać mieli tylko silni... A przynajmniej tak mówią.', 0),
(15772, 'koKR', 'Wychowałaś wszystkich tutejszych orków, Wszechmatko?', 'Wychowałaś wszystkich tutejszych orków, Wszechmatko?', 0),
(15773, 'koKR', '', 'Tutaj dorastali. Chroniliśmy ich przed krzywdą. Robiliśmy, co w naszej mocy, by przywrócić im zdrowie. Wielu zmarło, ale o wiele, wiele więcej wyrosło na silnych. Jak Garosz...$B$B<Wszechmatka Geyah wzdycha.>$B$BWiesz, on stracił serce. Mówi mi, że jestem jego równowagą. Że beze mnie ogarnie go żądza krwi, która pochłonęła jego ojca i w końcu przeklęła nasz lud.', 0),
(15774, 'koKR', 'Wierzysz w to?', 'Wierzysz w to?', 0),
(15775, 'koKR', '', '<Wszechmatka Geyah śmieje się słabo.>$B$BOczywiście, że nie, $gmój drogi:moja droga;. Ale to nie ja muszę w to wierzyć...$B$BGarosz może przewodzić Mag\'harom. Jest silny i mądry. Wszystkie duchy mu sprzyjają. Musi tylko uwierzyć w siebie. Tak wiele się boi... Tak głęboko się lęka, że jeśli puści wodze, jego gniew pochłonie jego samego i wszystkich wokół.', 0),
(15776, 'koKR', 'Co można zrobić? $GPróbowałem:Próbowałam; już wielu sposobów. $GRobiłem:Robiłam;, co w mojej mocy, by pomóc mieszkańcom Nagrandu. Za każdym razem, gdy $gpodchodziłem:podchodziłam; do Garosza, zbywał mnie.', 'Co można zrobić? $GPróbowałem:Próbowałam; już wielu sposobów. $GRobiłem:Robiłam;, co w mojej mocy, by pomóc mieszkańcom Nagrandu. Za każdym razem, gdy $gpodchodziłem:podchodziłam; do Garosza, zbywał mnie.', 0),
(15777, 'koKR', '', 'Chciałabym wiedzieć, $gmój drogi:moja droga;. Nie posłucha ani ciebie, ani mnie. Prawdę mówiąc, dlatego wciąż tu jestem. Dlatego nie odeszłam z Matką Kashur. On musi odnaleźć swoje serce. Bez przywództwa nasz lud nie przetrwa zimy.', 0),
(15778, 'koKR', 'Odejść? Jak można samemu wybrać odejście?', 'Odejść? Jak można samemu wybrać odejście?', 0),
(15779, 'koKR', '', '<Wszechmatka Geyah się uśmiecha.>$B$BJestem stara. Nadszedł mój czas. Gdy odejdę, mój duch przejdzie do krainy duchów. Tam stanę u boku przodków. Stamtąd będziemy czuwać nad naszym ludem.$B$BGdy Garad żył, obowiązek Matki Kashur był taki sam jak mój teraz.', 0),
(15780, 'koKR', 'Co to za obowiązek?', 'Co to za obowiązek?', 0),
(15781, 'koKR', '', 'Obowiązkiem matki klanu jest słuchać. Słuchać wiatru i wody, ognia i ziemi. Zbierać wieści dla swojego klanu tak, jak inni zbierają futra, by się ogrzać. Obcuję z duchami... W snach Matka Kashur przemawia do mnie tak, jak niegdyś przemawiały do niej duchy... Gdy odejdę, w ten sam sposób będę przemawiać do Drakii i Celestine.$B$B<Wszechmatka Geyah się uśmiecha.>', 0),
(15782, 'koKR', 'Czy mogę coś dla ciebie zrobić, Wszechmatko?', 'Czy mogę coś dla ciebie zrobić, Wszechmatko?', 0),
(16844, 'koKR', '', 'Co powiedział ci Garosz, $n?', 0),
(16845, 'koKR', 'Garosza nie da się już ocalić, Wszechmatko. Obawiam się, że pomagając Mag\'harom, $gprzekonałem:przekonałam; Garosza, że nie nadaje się na przywódcę.\n', 'Garosza nie da się już ocalić, Wszechmatko. Obawiam się, że pomagając Mag\'harom, $gprzekonałem:przekonałam; Garosza, że nie nadaje się na przywódcę.\n', 0),
(16848, 'koKR', '', '<Wszechmatka Geyah kiwa głową, przyjmując twoją odpowiedź.>$B$BNie mogę już walczyć z duchami, $n. Mój czas dawno minął. Raz jeszcze muszę ci podziękować za wszystko, co $gzrobiłeś:zrobiłaś;. Choć Garosza nic nie poruszy, twoje dokonania dodały otuchy wielu z mojego ludu. Są teraz gotowi walczyć o nasze prawa jako zjednoczony klan.', 0),
(16849, 'koKR', '$GZrobiłem:Zrobiłam; wszystko, co $gmogłem:mogłam;, Wszechmatko. Dziękuję ci za dobre słowa.', '$GZrobiłem:Zrobiłam; wszystko, co $gmogłem:mogłam;, Wszechmatko. Dziękuję ci za dobre słowa.', 0),
(16850, 'koKR', '', '<Wszechmatka Geyah uśmiecha się do ciebie.>$B$BPrzypominasz mi mojego syna, $n.$B$BByło w nim coś z niewzruszonej góry: filar siły i honoru.$B$B<Oczy Geyah wypełniają się łzami.>$B$BPoświęcił się, byśmy mogli przetrwać. By kolejne pokolenia orków mogły rodzić się w świecie bez klątwy krwi... Bez Gul\'dana i jego mrocznej Hordy...$B$B<Geyah wpatruje się w dal, pogrążona w myślach.>$B$BOch, Durotanie, jakże chciałabym, żebyś tu był. Twój lud tak rozpaczliwie cię potrzebuje...', 0),
(16851, 'koKR', 'Wszechmatko, jesteś matką Durotana?', 'Wszechmatko, jesteś matką Durotana?', 0),
(16852, 'koKR', '', '<Wszechmatka Geyah kiwa głową.>$B$B$GZnałeś:Znałaś; mojego syna?', 0),
(16853, 'koKR', 'Wszechmatko, nie $gmiałem:miałam; tego zaszczytu. Durotan zginął na długo przed moimi czasami, ale jego bohaterskie czyny zna każdy w moim świecie. Orkowie z Azeroth mieszkają w krainie zwanej Durotarem, nazwanej na cześć twojego syna. I... <Bierzesz oddech i zastanawiasz się, co za chwilę powiesz Wszechmatce.>\n', 'Wszechmatko, nie $gmiałem:miałam; tego zaszczytu. Durotan zginął na długo przed moimi czasami, ale jego bohaterskie czyny zna każdy w moim świecie. Orkowie z Azeroth mieszkają w krainie zwanej Durotarem, nazwanej na cześć twojego syna. I... <Bierzesz oddech i zastanawiasz się, co za chwilę powiesz Wszechmatce.>\n', 0),
(16854, 'koKR', '', '<Fioletowe oczy Wszechmatki Geyah wpatrują się w twoje.>$B$BTak...', 0),
(16855, 'koKR', 'Chodzi o mojego wodza, Wszechmatko. Przywódcę mojego ludu. Z mojego świata. On... On jest synem Durotana. To twój wnuk.', 'Chodzi o mojego wodza, Wszechmatko. Przywódcę mojego ludu. Z mojego świata. On... On jest synem Durotana. To twój wnuk.', 0),
(16856, 'koKR', '', '<Łzy spływają po twarzy Wszechmatki Geyah.>$B$BJa... ja... Durotan przeżył na tyle długo, by mieć dziecko? Dziecko, o którym Draka mówiła mi, zanim odeszli... To był ich największy lęk... Wychować dziecko w tym świecie. Po drugiej stronie tamtej bramy była ich jedyna nadzieja. Nie śmiałam powiedzieć tego Durotanowi, ale w tajemnicy błagałam duchy, by nad nimi czuwały – by chroniły ich dziecko i dały im siłę.$B$BJa... muszę zobaczyć mojego wnuka. Muszę go zobaczyć. Proszę, jestem zbyt słaba. Musisz mu powiedzieć. Zanim opuszczę ten świat...\n', 0),
(16857, 'koKR', 'Natychmiast wracam do Azeroth, Wszechmatko.', 'Natychmiast wracam do Azeroth, Wszechmatko.', 0),
(17101, 'koKR', '', 'Czekałam na ciebie, dziecko. Podejdź bliżej – moje oczy nie są już tak bystre jak kiedyś.\n', 0),
(17120, 'koKR', '', 'Tak, poruszasz się jak mój syn. Masz jego szerokie ramiona – ach, i dzikie oczy swojej matki.\n', 0),
(17123, 'koKR', '', 'Nie ma wątpliwości – jesteś dziedzicem Durotana... moim wnukiem. Draka mówiła mi, że nosi dziecko, zanim wraz z twoim ojcem opuściła nasz świat, ale nigdy nie śmiałam marzyć, że przeżyją...\n', 0),
(17126, 'koKR', '', 'Thrall? Niewolnik? Byłeś niewolnikiem jedynie przeszłości, wnuku! Ale już nie! Kiedy ostatni raz go widziałam, Durotan zdradził mi imię, jakie nada nienarodzonemu synowi... Był... taki dumny...', 0),
(17129, 'koKR', '', 'Błogosławione duchy! Przez dwadzieścia lat wiedzieliśmy tylko tyle, że Grom jako pierwszy napił się z przeklętego kielicha i sprowadził zgubę na nasz lud... To jedyna prawda, jaką kiedykolwiek znał jego syn, Garosz.\n', 0),
(17131, 'koKR', '', 'Wnuku, czy ty... Czy powiesz Garoszowi to, co mnie powiedziałeś o jego ojcu?', 0),
(17806, 'koKR', 'Więc dopiero co $gprzybyłeś:przybyłaś; z Azeroth, co? Lepiej się zahartuj, $N – ta kraina kryje niebezpieczeństwa, z jakimi Horda nigdy wcześniej się nie mierzyła. Jestem Nazgrel – prawa ręka naszego potężnego wodza, Thralla. Zaszczycił mnie zadaniem ochrony tej dzielnej wyprawy i – na wszystkie duchy – wywiążę się z niego!', '', 0),
(17895, 'koKR', 'Opowiedz mi więcej o naszej misji tutaj, Nazgrelu.', 'Opowiedz mi więcej o naszej misji tutaj, Nazgrelu.', 0),
(17896, 'koKR', 'Gdy tylko nasz wódz usłyszał, że Mroczny Portal znów się otworzył, natychmiast zebrał doradców, by zaplanować tę śmiałą wyprawę. Choć niektórzy z nich mają wątpliwości, Thrall żywi nadzieję, że dowiemy się czegoś nowego o historii naszego ludu. Wierzy, że gdzieś wśród ruin tego świata kryje się prawdziwa opowieść o orkach.$B$BMuszę przyznać, że w najczarniejszych chwilach... obawiam się, że ta opowieść powinna pozostać nieopowiedziana.', '', 0),
(17897, 'koKR', '<Słuchaj dalej>', '<Słuchaj dalej>', 0),
(17898, 'koKR', 'Horda wiele zaryzykowała, wyruszając do Rubieży – zasoby, ludzi, a nawet obronę własnych ziem. Mimo wszystko Thrall wierzy w obietnicę tej zniszczonej krainy. W jego oczach pojawił się ostatnio dziwny blask – jakby przeczuwał jakieś objawienie, którego reszta z nas nie dostrzega.$B$BA jednak to mój wódz i mój brat krwi. Poszedłbym za nim nawet przez bramy otchłani.', '', 0),
(17926, 'koKR', '', '%s ociera łzę.', 0),
(17927, 'koKR', '', 'Go\'el. Jesteś Go\'el, syn Durotana – prawowity wódz Mroźnych Wilków. Tego dnia, wnuku, jesteś największą radością mojego serca.\n', 0),
(17929, 'koKR', '', 'Widzę, że dzierżysz Zgładziciela. Czy wszyscy nasi najwięksi bohaterowie polegli, wnuku?\n', 0),
(17930, 'koKR', '', 'A co z Grommaszem? Co z Piekłoryczem?\n', 0),
(18593, 'koKR', '', 'Mów szybko; nie mam czasu na czcze pogawędki. Porzuceni stali się siłą, z którą trzeba się liczyć, ale każdego dnia wciąż jest wiele do zrobienia. To miasto samo się nie poprowadzi.$b$bCzego chcesz?', 0),
(19197, 'koKR', '', '%s spogląda na porzucony naszyjnik. Pogrążona w smutku pani rzuca czar złudzenia, który przywołuje duchy Wysoko Urodzonych. Komnatę wypełnia ich pradawna pieśń o sin\'dorei...', 0),
(19244, 'koKR', '', 'Wzdychając, %s klęka i podnosi amulet.', 0),
(19263, 'koKR', '', 'Belore...', 0),
(20609, 'koKR', 'Archibald jest mistrzem kuszy. To mistrz broni Podmiasta, znajdziesz go w Dzielnicy Wojennej.', 'Archibald jest mistrzem kuszy. To mistrz broni Podmiasta, znajdziesz go w Dzielnicy Wojennej.', 0),
(20611, 'koKR', 'Sayoc, ten brzydki ork tutaj, nauczy cię walki sztyletami. Jak chcesz się uczyć gdzie indziej, gadaj z Iledą na Placu Obieżyświatów w Srebrnej Lunie albo z Archibaldem w Dzielnicy Wojennej Podmiasta, dobra?', 'Sayoc, ten brzydki ork tutaj, nauczy cię walki sztyletami. Jak chcesz się uczyć gdzie indziej, gadaj z Iledą na Placu Obieżyświatów w Srebrnej Lunie albo z Archibaldem w Dzielnicy Wojennej Podmiasta, dobra?', 0),
(20613, 'koKR', 'Chcesz walić pięściami, co? Sayoc, o tu, cię nauczy.', 'Chcesz walić pięściami, co? Sayoc, o tu, cię nauczy.', 0),
(20614, 'koKR', 'Strzelania z broni palnej uczy Ansekhwa, taureński mistrz broni na dolnym środkowym wzniesieniu Gromowych Urwisk.', 'Strzelania z broni palnej uczy Ansekhwa, taureński mistrz broni na dolnym środkowym wzniesieniu Gromowych Urwisk.', 0),
(20615, 'koKR', 'Walki maczugami uczy Ansekhwa, którego znajdziesz na dolnym środkowym wzniesieniu Gromowych Urwisk.', 'Walki maczugami uczy Ansekhwa, którego znajdziesz na dolnym środkowym wzniesieniu Gromowych Urwisk.', 0),
(20616, 'koKR', 'Mistrz broni Porzuconych, Archibald, zna się na broni drzewcowej. Szkoli innych w Dzielnicy Wojennej Podmiasta. Właściwe techniki może ci też pokazać Ileda, mistrzyni broni krwawych elfów z Placu Obieżyświatów w Srebrnej Lunie.', 'Mistrz broni Porzuconych, Archibald, zna się na broni drzewcowej. Szkoli innych w Dzielnicy Wojennej Podmiasta. Właściwe techniki może ci też pokazać Ileda, mistrzyni broni krwawych elfów z Placu Obieżyświatów w Srebrnej Lunie.', 0),
(20618, 'koKR', 'Hanashi tutaj zna się na kosturach. Jeśli chcesz solidniejszego nauczyciela, idź do Gromowych Urwisk. Ansekhwa nauczy cię tam, na dolnym środkowym wzniesieniu.', '', 0),
(20619, 'koKR', 'Ileda z krwawych elfów, którą znajdziesz na Placu Obieżyświatów w Srebrnej Lunie, uczy swoich uczniów walki mieczami jednoręcznymi i dwuręcznymi. Archibald, mistrz broni Podmiasta, też może cię wyszkolić; jest w Dzielnicy Wojennej.', 'Ileda z krwawych elfów, którą znajdziesz na Placu Obieżyświatów w Srebrnej Lunie, uczy swoich uczniów walki mieczami jednoręcznymi i dwuręcznymi. Archibald, mistrz broni Podmiasta, też może cię wyszkolić; jest w Dzielnicy Wojennej.', 0),
(20621, 'koKR', 'Archibald to mistrz kuszy. On mistrz broni Podmiasta, siedzi w Dzielnicy Wojennej.', 'Archibald to mistrz kuszy. On mistrz broni Podmiasta, siedzi w Dzielnicy Wojennej.', 0),
(20622, 'koKR', 'Nasz nauczyciel strzelania to Ansekhwa, taureński mistrz broni na dolnym środkowym wzniesieniu Gromowych Urwisk.', 'Nasz nauczyciel strzelania to Ansekhwa, taureński mistrz broni na dolnym środkowym wzniesieniu Gromowych Urwisk.', 0),
(20623, 'koKR', 'Maczugi? Tego uczy Ansekhwa, znajdziesz go na dolnym środkowym wzniesieniu Gromowych Urwisk.', 'Maczugi? Tego uczy Ansekhwa, znajdziesz go na dolnym środkowym wzniesieniu Gromowych Urwisk.', 0),
(20624, 'koKR', 'Mistrz broni Porzuconych, Archibald, zna się na broni drzewcowej jak mało kto. Szkoli innych w Dzielnicy Wojennej Podmiasta. Ileda, mistrzyni broni krwawych elfów z Placu Obieżyświatów w Srebrnej Lunie, też pokaże ci, jak to się robi.', 'Mistrz broni Porzuconych, Archibald, zna się na broni drzewcowej jak mało kto. Szkoli innych w Dzielnicy Wojennej Podmiasta. Ileda, mistrzyni broni krwawych elfów z Placu Obieżyświatów w Srebrnej Lunie, też pokaże ci, jak to się robi.', 0),
(20625, 'koKR', 'Ileda z krwawych elfów, z Placu Obieżyświatów w Srebrnej Lunie, uczy swoich uczniów walki mieczami jedno- i dwuręcznymi. Archibald, mistrz broni Podmiasta, też cię wyszkoli. Siedzi w Dzielnicy Wojennej.', 'Ileda z krwawych elfów, z Placu Obieżyświatów w Srebrnej Lunie, uczy swoich uczniów walki mieczami jedno- i dwuręcznymi. Archibald, mistrz broni Podmiasta, też cię wyszkoli. Siedzi w Dzielnicy Wojennej.', 0),
(20765, 'koKR', 'Cytadela Piekielnego Ognia jest nasza! Źródło armii spaczonych orków Illidana przestało istnieć! Magtheridon padł z ręki $n i $gjego:jej; sojuszników!', '', 0),
(20766, 'koKR', 'Nadszedł czas, by powstać i uderzyć na pozostałe spaczone orki! Zróbcie to dla swojego wodza! Zróbcie to dla Hordy!\n', '', 0),
(22106, 'koKR', 'Cały dzień zbieram części do sterowca, a Frezza nie ma nawet tyle przyzwoitości, żeby płacić mi od godziny. Ale nie po to tu jesteś, co? Założę się, że chcesz wiedzieć, gdzie jest sterowiec. No to masz szczęście – mam tu swój lokalizator sterowców!', 'Cały dzień zbieram części do sterowca, a Frezza nie ma nawet tyle przyzwoitości, żeby płacić mi od godziny. Ale nie po to tu jesteś, co? Założę się, że chcesz wiedzieć, gdzie jest sterowiec. No to masz szczęście – mam tu swój lokalizator sterowców!', 0),
(22108, 'koKR', 'Gdzie jest teraz sterowiec do Podmiasta?', 'Gdzie jest teraz sterowiec do Podmiasta?', 0),
(22199, 'koKR', 'Gdzie jest teraz sterowiec do Grom\'gol?', 'Gdzie jest teraz sterowiec do Grom\'gol?', 0),
(24486, 'koKR', 'Jesteśmy otoczeni... Wrogowie napierają ze wszystkich stron, młody Piekłoryczu.', '', 0),
(24487, 'koKR', 'Plaga spada z północy jak szarańcza.', '', 0),
(24488, 'koKR', 'Przymierze trzyma jedyny bezpieczny szlak żeglugowy w tym regionie, a i ten mogą mu odebrać te przeklęte mgły.', '', 0),
(24489, 'koKR', 'Jedyny port, przez który możemy dostać zaopatrzenie, trzymają Porzuceni po drugiej stronie tego przeklętego kontynentu!', '', 0),
(24490, 'koKR', 'Wszystko, czego nie uniosą nasze sterowce, trzeba przywieźć statkiem i przewieźć przez całą Północną Grań, zanim do nas dotrze.', '', 0),
(24493, 'koKR', 'Machiny oblężnicze, amunicja, ciężkie zbroje... Jak zamierzasz bez nich skruszyć mury Lodowej Korony?', '', 0),
(24497, 'koKR', 'Syn marnotrawny przemówił!', '', 0),
(24498, 'koKR', 'Krew twojego ojca płynie w tobie mocno, Piekłoryczu. Niecierpliwy jak zawsze... Niecierpliwy i lekkomyślny.', '', 0),
(24500, 'koKR', 'Rzucasz się na oślep w otwartą wojnę, nie myśląc o konsekwencjach.', '', 0),
(24502, 'koKR', 'Piłem tę samą krew co twój ojciec, Garoszu. Przeklęty jad Mannorotha płynął także w moich żyłach.', '', 0),
(24503, 'koKR', 'Wbijałem broń w ciała i umysły moich wrogów.', '', 0),
(24504, 'koKR', 'I choć Grom zginął chwalebną śmiercią – uwalniając nas wszystkich od klątwy krwi – nie zdołał wymazać strasznej pamięci o naszej przeszłości.', '', 0),
(24505, 'koKR', 'Jego czyn nie mógł wymazać okropieństw, których się dopuściliśmy.', '', 0),
(24506, 'koKR', '%s milknie na chwilę.', '', 0),
(24507, 'koKR', 'Zimą po zdjęciu klątwy setki starych wojowników takich jak ja uległy rozpaczy.', '', 0),
(24508, 'koKR', 'Nasze umysły były wreszcie wolne, tak... Wolne, by na nowo przeżywać wszystkie niewyobrażalne czyny, których dopuściliśmy się pod wpływem Legionu.', '', 0),
(24509, 'koKR', '%s kiwa głową.', '', 0),
(24510, 'koKR', 'Chyba najbardziej wytrącały ich z równowagi odgłosy draenejskich dzieci... Tego się nie zapomina...', '', 0),
(24511, 'koKR', 'Byłeś kiedyś na Farmie Ostroknur? Kiedy świnie dorastają do uboju... To ten dźwięk. Dźwięk zarzynanych świń... On rozbrzmiewa najgłośniej. To ciężkie chwile dla nas, starych weteranów.', '', 0),
(24513, 'koKR', '%s kręci głową.', '', 0),
(24515, 'koKR', 'Nie mówię tylko o dzieciach naszych wrogów...', '', 0),
(24516, 'koKR', 'Nie pozwolę ci znów poprowadzić nas tą mroczną ścieżką, młody Piekłoryczu. Prędzej sam cię zabiję, niż do tego dopuszczę...', '', 0),
(24519, 'koKR', 'Nie jadam wieprzowiny...', '', 0),
(24520, 'koKR', '%s spluwa.', '', 0),
(24537, 'koKR', 'Strach zawsze był naszą największą bronią. Całe wojny wygrywano i przegrywano na chwiejnych barkach lęku i zwątpienia. Jak więc walczyć z wrogiem, który nie zna strachu?$B$B<Zaurzykieł kręci głową.>$B$BW Północnej Grani nie walczymy tylko z Plagą, walczymy o to, by zapanować nad własnymi zmysłami, zanim nas rozszarpią...\n', '', 0),
(32232, 'koKR', 'Co się dzieje?\n', 'Co się dzieje?\n', 0),
(32233, 'koKR', 'Co tu robią ci wszyscy Porzuceni?\n', 'Co tu robią ci wszyscy Porzuceni?', 0),
(32235, 'koKR', 'Żądamy odpowiedzi!', 'Żądamy odpowiedzi!', 0),
(32236, 'koKR', 'Gdzie jest wódz?', 'Gdzie jest wódz?', 0),
(32237, 'koKR', 'Kiedy będziemy mogli znów otworzyć sklepy? Tracę tu złoto!', 'Kiedy będziemy mogli znów otworzyć sklepy? Tracę tu złoto!', 0),
(32238, 'koKR', 'To oburzające!', 'To oburzające!', 0),
(32239, 'koKR', 'Czemu Thrall pozwala, żeby to się działo w naszym mieście?', 'Czemu Thrall pozwala, żeby to się działo w naszym mieście?', 0),
(32240, 'koKR', 'CISZA!', '', 0),
(32241, 'koKR', 'Stoimy na krawędzi otwartej wojny z Przymierzem!', '', 0),
(32242, 'koKR', 'W Północnej Grani doszło do tragicznych wydarzeń. Wódz robi wszystko, co może, by zapewnić nam bezpieczeństwo.', '', 0),
(32243, 'koKR', 'Wszystkie usługi i sklepy mają pozostać zamknięte aż do odwołania! To wszystko!', '', 0),
(32290, 'koKR', '', 'Lady Proudmoore, wódz mówi prawdę. Ten podstęp uknuli Varimathras i wielki aptekarz Putress. To nie była sprawka Hordy.', 0),
(32291, 'koKR', '', 'Gdy połączone siły Hordy i Przymierza rozpoczęły szturm na Bramę Gniewu, w Podmieście wybuchło powstanie. Varimathras i hordy jego demonicznych pobratymców zaatakowali. W zamachu zginęły setki moich poddanych. Ledwie uszłam z życiem.', 0),
(35225, 'koKR', 'Czy jesteś $ggotów:gotowa; walczyć za Hordę, $N?', 'Czy jesteś $ggotów:gotowa; walczyć za Hordę, $N?', 0),
(35333, 'koKR', 'Przez lata służyłem w tym zapomnianym zakątku świata, poznając teren i czekając na swoją chwilę. W końcu nadszedł nasz czas. Cała potęga Orgrimmaru zwraca się teraz ku Aszarze, naszej bramie do Jesionowej Kniei i do panowania nad tym kontynentem. Witaj na linii frontu, $N.', '', 0),
(35457, 'koKR', 'Duchy żywiołów są mądre. Były tu na długo przed nami i przetrwają długo po nas. Gdy do nas przemawiają, musimy słuchać.', '', 0),
(45395, 'koKR', 'Hej, hej.$B$BChcesz oddać swoje zwierzaki do stajni czy szukasz zaginionego towarzysza?', 'Hej, hej.$B$BChcesz oddać swoje zwierzaki do stajni czy szukasz zaginionego towarzysza?', 0),
(45396, 'koKR', 'Hej, hej.$B$BPotrzebujesz pomocy w odnalezieniu zaginionego towarzysza?', 'Hej, hej.$B$BPotrzebujesz pomocy w odnalezieniu zaginionego towarzysza?', 0),
(45865, 'koKR', '', 'Lepszej broni palnej nie znajdziesz nigdzie w Orgrimmarze.', 0),
(45914, 'koKR', 'Co się dzieje?', 'Co się dzieje?', 0),
(46529, 'koKR', 'Przybywasz, by wesprzeć sprawę? Góra Hyjal płonie!', '', 0),
(46620, 'koKR', 'To oburzające!', 'To oburzające!', 0),
(56291, 'koKR', 'Czego chcesz?', 'Czego chcesz?', 0);
